/** Editorial translations keyed by the exact Portuguese copy stored in tool-articles.ts. */
export const editorialTranslations: Record<string, { en: string; es: string }> = {
  'Tokenização de ativos reais: o que o token representa?': { en: 'Tokenization of real-world assets: what does the token represent?', es: 'Tokenización de activos reales: ¿qué representa el token?' },
  'Entenda a diferença entre registrar um token e possuir direitos sobre o ativo, além de custódia e liquidez.': { en: 'Understand the difference between recording a token and holding rights to the asset, as well as custody and liquidity.', es: 'Comprende la diferencia entre registrar un token y tener derechos sobre el activo, además de la custodia y la liquidez.' },
  'Tokenização cria uma representação digital': { en: 'Tokenization creates a digital representation', es: 'La tokenización crea una representación digital' },
  'Tokenização representa direitos ou instrumentos em um registro digital, como uma blockchain. O token representa um ativo financeiro ou real somente na medida em que contratos, registros e leis aplicáveis reconhecem essa ligação. Possuir o token não significa automaticamente ser proprietário direto de imóvel, título ou participação.': { en: 'Tokenization represents rights or instruments in a digital ledger, such as a blockchain. A token represents a financial or real-world asset only to the extent that applicable contracts, records, and laws recognize that link. Owning the token does not automatically make you the direct owner of property, a security, or an equity stake.', es: 'La tokenización representa derechos o instrumentos en un registro digital, como una blockchain. Un token representa un activo financiero o real solo en la medida en que los contratos, registros y leyes aplicables reconozcan ese vínculo. Ser titular del token no te convierte automáticamente en propietario directo de un inmueble, un título o una participación.' },
  'O FMI descreve instrumentos tradicionais, como depósitos e cotas de fundos, representados em registros digitais. A tecnologia pode alterar emissão e liquidação, mas não elimina custódia, validade jurídica, governança e riscos operacionais.': { en: 'The IMF describes traditional instruments, such as deposits and fund shares, represented on digital ledgers. The technology may change issuance and settlement, but it does not eliminate custody, legal validity, governance, or operational risks.', es: 'El FMI describe instrumentos tradicionales, como depósitos y participaciones de fondos, representados en registros digitales. La tecnología puede cambiar la emisión y la liquidación, pero no elimina la custodia, la validez jurídica, la gobernanza ni los riesgos operativos.' },
  'Quais direitos acompanham o token?': { en: 'What rights come with the token?', es: '¿Qué derechos incluye el token?' },
  'Identifique emissor, entidade que mantém o ativo, documento que estabelece direitos e forma de resolver disputas. Procure regras de transferência e resgate, restrições geográficas, prioridade em insolvência, custos e registros que confirmem a relação com o ativo.': { en: 'Identify the issuer, the entity holding the asset, the document establishing the rights, and how disputes are resolved. Look for transfer and redemption rules, geographic restrictions, priority in insolvency, costs, and records confirming the link to the asset.', es: 'Identifica al emisor, la entidad que custodia el activo, el documento que establece los derechos y la forma de resolver disputas. Busca las reglas de transferencia y canje, las restricciones geográficas, la prioridad en caso de insolvencia, los costos y los registros que confirmen el vínculo con el activo.' },
  'Um explorador pode mostrar que tokens existem e foram transferidos, mas não confirma sozinho a validade de registros fora da blockchain. Documentos legais e registros reconhecidos têm papel próprio.': { en: 'A blockchain explorer may show that tokens exist and have been transferred, but it cannot by itself confirm the validity of records outside the blockchain. Legal documents and recognized registries serve their own purpose.', es: 'Un explorador puede mostrar que existen tokens y que se han transferido, pero no confirma por sí solo la validez de los registros externos a la blockchain. Los documentos legales y los registros reconocidos cumplen una función propia.' },
  'A infraestrutura pode continuar dependendo de intermediários': { en: 'The infrastructure may still depend on intermediaries', es: 'La infraestructura puede seguir dependiendo de intermediarios' },
  'Uma oferta pode depender de custodiante, administrador, emissor, provedor de identidade, operador de rede ou serviço de dados. Automatizar uma etapa de liquidação não garante mercado secundário profundo nem resgate imediato.': { en: 'An offering may depend on a custodian, administrator, issuer, identity provider, network operator, or data service. Automating one settlement step does not guarantee a deep secondary market or immediate redemption.', es: 'Una oferta puede depender de un custodio, administrador, emisor, proveedor de identidad, operador de red o servicio de datos. Automatizar una etapa de liquidación no garantiza un mercado secundario profundo ni un canje inmediato.' },
  'Relatórios do FMI e BIS discutem potenciais eficiências e riscos da tokenização. São análises institucionais, não endosso a um produto. Confira data, escopo e jurisdição antes de aplicar uma conclusão.': { en: 'IMF and BIS reports discuss potential efficiencies and risks of tokenization. These are institutional analyses, not endorsements of a product. Check the date, scope, and jurisdiction before applying a conclusion.', es: 'Los informes del FMI y del BIS analizan posibles eficiencias y riesgos de la tokenización. Son análisis institucionales, no un respaldo a ningún producto. Comprueba la fecha, el alcance y la jurisdicción antes de aplicar una conclusión.' },
  'Riscos de mercado, liquidez e tecnologia': { en: 'Market, liquidity, and technology risks', es: 'Riesgos de mercado, liquidez y tecnología' },
  'O token pode negociar longe do valor de referência ou em mercado restrito. Também há riscos de contrato, oráculo, chave administrativa, bridge ou sistema de identidade. Divergência entre registros on-chain e externos pode gerar conciliação e disputas.': { en: 'The token may trade far from its reference value or in a limited market. Contract, oracle, admin-key, bridge, and identity-system risks may also apply. Differences between on-chain and external records can lead to reconciliation issues and disputes.', es: 'El token puede cotizar lejos de su valor de referencia o en un mercado limitado. También existen riesgos relacionados con contratos, oráculos, claves administrativas, bridges y sistemas de identidad. Las discrepancias entre los registros on-chain y externos pueden generar conciliaciones y disputas.' },
  'Leia como atualizações são autorizadas, como se responde à perda de chave e qual sistema mantém registros e pagamentos. Código verificado ou auditoria técnica não substituem análise de direitos e contraparte.': { en: 'Read how upgrades are authorized, how key loss is handled, and which system maintains records and processes payments. Verified code or a technical audit cannot replace an analysis of rights and counterparties.', es: 'Lee cómo se autorizan las actualizaciones, cómo se responde a la pérdida de claves y qué sistema mantiene los registros y procesa los pagos. El código verificado o una auditoría técnica no sustituyen el análisis de los derechos y las contrapartes.' },
  'Roteiro para separar narrativa e direito': { en: 'A guide to separating the narrative from the legal rights', es: 'Guía para separar la narrativa de los derechos legales' },
  'Resuma qual direito é oferecido. Identifique emissor, custodiante, documento vinculante, jurisdição, resgate, restrições e riscos tecnológicos. Compare a divulgação com documentos oficiais; não preencha lacunas com suposições.': { en: 'Summarize which right is being offered. Identify the issuer, custodian, binding document, jurisdiction, redemption terms, restrictions, and technology risks. Compare disclosures with official documents; do not fill gaps with assumptions.', es: 'Resume qué derecho se ofrece. Identifica al emisor, custodio, documento vinculante, jurisdicción, condiciones de canje, restricciones y riesgos tecnológicos. Compara la información divulgada con los documentos oficiales; no rellenes lagunas con suposiciones.' },
  'O enquadramento regulatório depende do produto e da jurisdição. Este artigo explica conceitos e não avalia ofertas nem recomenda investimentos.': { en: 'Regulatory treatment depends on the product and jurisdiction. This article explains concepts; it does not assess offerings or recommend investments.', es: 'El tratamiento regulatorio depende del producto y la jurisdicción. Este artículo explica conceptos; no evalúa ofertas ni recomienda inversiones.' },
  'Ordem a mercado, ordem limite e slippage em cripto': { en: 'Market orders, limit orders, and slippage in crypto', es: 'Órdenes de mercado, órdenes límite y slippage en cripto' },
  'Veja como tipo de ordem, spread e profundidade afetam execução e por que preço exibido pode não ser o final.': { en: 'See how order type, spread, and depth affect execution, and why the displayed price may not be the final price.', es: 'Descubre cómo el tipo de orden, el spread y la profundidad afectan la ejecución, y por qué el precio mostrado puede no ser el precio final.' },
  'Cotação não garante execução': { en: 'A quote does not guarantee execution', es: 'Una cotización no garantiza la ejecución' },
  'Num livro de ofertas, compradores indicam preços de compra e vendedores preços de venda. Melhor bid e ask formam o spread visível. Última negociação, índice e mark price podem ter definições distintas; uma tela deve informar qual mostra.': { en: 'In an order book, buyers place bids and sellers place asks. The best bid and ask form the visible spread. Last traded price, index price, and mark price may have different definitions; an interface should indicate which one it displays.', es: 'En un libro de órdenes, los compradores indican precios de compra y los vendedores, precios de venta. El mejor bid y ask forman el spread visible. El último precio negociado, el precio índice y el mark price pueden tener definiciones distintas; la pantalla debe indicar cuál muestra.' },
  'Uma ordem grande pode consumir várias ofertas e executar em preços diferentes. O resultado depende de profundidade, velocidade e regras da plataforma. A liquidez varia entre pares, exchanges e horários.': { en: 'A large order may consume several offers and execute at different prices. The outcome depends on market depth, speed, and platform rules. Liquidity varies across pairs, exchanges, and times of day.', es: 'Una orden grande puede consumir varias ofertas y ejecutarse a distintos precios. El resultado depende de la profundidad, la velocidad y las reglas de la plataforma. La liquidez varía según el par, el exchange y la hora.' },
  'Ordem a mercado prioriza execução': { en: 'A market order prioritizes execution', es: 'Una orden de mercado prioriza la ejecución' },
  'Uma ordem a mercado aceita os preços disponíveis para tentar executar rapidamente; não fixa o preço final. Em mercado rápido ou raso, slippage pode ser relevante. A execução também pode ser parcial conforme as regras.': { en: 'A market order accepts available prices in an attempt to execute quickly; it does not fix the final price. Slippage can be significant in fast-moving or shallow markets. Depending on the rules, execution may also be partial.', es: 'Una orden de mercado acepta los precios disponibles para intentar ejecutarse rápidamente; no fija el precio final. El slippage puede ser importante en mercados rápidos o poco profundos. La ejecución también puede ser parcial según las reglas.' },
  'A FINRA explica, no contexto de ações, que stops podem acionar ordem a mercado cujo preço difere do gatilho. Exchanges cripto implementam seus tipos de ordem segundo regras próprias.': { en: 'FINRA explains, in the context of stocks, that a stop may trigger a market order whose price differs from the trigger. Crypto exchanges implement order types according to their own rules.', es: 'FINRA explica, en el contexto de las acciones, que un stop puede activar una orden de mercado cuyo precio difiera del precio de activación. Los exchanges de cripto implementan sus tipos de órdenes según sus propias reglas.' },
  'Ordem limite prioriza o preço': { en: 'A limit order prioritizes price', es: 'Una orden límite prioriza el precio' },
  'Uma ordem limite compra no preço limite ou abaixo, ou vende no limite ou acima. Pode não executar, ser parcial ou esperar enquanto o mercado se afasta. O limite controla o preço da ordem, mas não garante preenchimento.': { en: 'A limit order buys at the limit price or lower, or sells at the limit price or higher. It may not execute, may be partially filled, or may remain pending as the market moves away. The limit controls the order price, but does not guarantee a fill.', es: 'Una orden límite compra al precio límite o por debajo, o vende al límite o por encima. Puede no ejecutarse, ejecutarse parcialmente o quedar pendiente mientras el mercado se aleja. El límite controla el precio de la orden, pero no garantiza que se complete.' },
  'Opções como post-only, reduce-only ou tempo em vigor mudam comportamento em alguns produtos. Em swaps, tolerância de slippage não é necessariamente igual a uma ordem limite tradicional.': { en: 'Options such as post-only, reduce-only, or time-in-force change behavior in some products. In swaps, slippage tolerance is not necessarily the same as a traditional limit order.', es: 'Opciones como post-only, reduce-only o tiempo en vigor cambian el comportamiento de algunos productos. En los swaps, la tolerancia al slippage no equivale necesariamente a una orden límite tradicional.' },
  'Spread e profundidade ajudam a estimar impacto': { en: 'Spread and depth help estimate market impact', es: 'El spread y la profundidad ayudan a estimar el impacto' },
  'Observe spread e quantidade disponível em vários níveis do livro. Uma ordem maior que o primeiro nível pode atravessar os seguintes. Profundidade visível pode mudar antes da execução e não inclui necessariamente liquidez de outros locais.': { en: 'Check the spread and available quantity at several order-book levels. An order larger than the first level may sweep through the next ones. Visible depth can change before execution and may not include liquidity from other venues.', es: 'Observa el spread y la cantidad disponible en varios niveles del libro. Una orden mayor que el primer nivel puede recorrer los siguientes. La profundidad visible puede cambiar antes de la ejecución y no necesariamente incluye la liquidez de otros mercados.' },
  'Volume diário alto sozinho não comprova execução barata para sua ordem. Considere taxas, liquidez acessível, funding e congestionamento, conforme o produto.': { en: 'High daily volume alone does not prove that your order will execute cheaply. Consider fees, accessible liquidity, funding, and congestion, depending on the product.', es: 'Un volumen diario alto no demuestra por sí solo que tu orden se ejecutará a bajo costo. Considera las comisiones, la liquidez accesible, el funding y la congestión, según el producto.' },
  'Planeje cenários e confira as regras': { en: 'Plan scenarios and check the rules', es: 'Planifica escenarios y consulta las reglas' },
  'Compare preço esperado, pior preço plausível, custos e possibilidade de não execução. Para stops, separe disparo, ordem enviada e preço executado. Em swaps, leia impacto estimado antes de assinar.': { en: 'Compare the expected price, a plausible worst-case price, costs, and the possibility of no execution. For stops, distinguish the trigger, the submitted order, and the execution price. For swaps, review estimated impact before signing.', es: 'Compara el precio esperado, un precio desfavorable plausible, los costos y la posibilidad de que no se ejecute. En los stops, distingue entre la activación, la orden enviada y el precio de ejecución. En los swaps, revisa el impacto estimado antes de firmar.' },
  'Calculadoras educativas não garantem preço de saída. O simulador de posição usa os preços inseridos, mas não substitui livro ao vivo nem regras do contrato.': { en: 'Educational calculators do not guarantee an exit price. The position simulator uses the prices you enter, but does not replace a live order book or the contract rules.', es: 'Las calculadoras educativas no garantizan un precio de salida. El simulador de posiciones utiliza los precios que introduces, pero no sustituye un libro de órdenes en vivo ni las reglas del contrato.' },
  'Memecoins: liquidez, concentração e riscos para analisar': { en: 'Memecoins: liquidity, concentration, and risks to assess', es: 'Memecoins: liquidez, concentración y riesgos que debes analizar' },
  'Um roteiro para investigar tokens, liquidez e permissões sem tratar indicadores como selo de segurança.': { en: 'A guide to investigating tokens, liquidity, and permissions without treating indicators as a seal of safety.', es: 'Una guía para investigar tokens, liquidez y permisos sin considerar los indicadores como un sello de seguridad.' },
  'Preço unitário baixo não significa projeto barato': { en: 'A low unit price does not mean a project is cheap', es: 'Un precio unitario bajo no significa que un proyecto sea barato' },
  'Uma moeda que custa frações de centavo não é automaticamente barata. Preço depende da oferta em circulação. Capitalização estimada multiplica preço pela oferta escolhida, mas oferta circulante, total e máxima podem divergir ou ser difíceis de verificar. Em tokens novos, preço e capitalização podem vir de um mercado pequeno.': { en: 'A coin priced at fractions of a cent is not automatically cheap. Price depends on circulating supply. Estimated market capitalization multiplies price by a chosen supply figure, but circulating, total, and maximum supply may differ or be difficult to verify. For new tokens, price and market cap may come from a small market.', es: 'Una moneda que cuesta fracciones de centavo no es automáticamente barata. El precio depende de la oferta circulante. La capitalización estimada multiplica el precio por la oferta elegida, pero la oferta circulante, total y máxima pueden diferir o ser difíciles de verificar. En tokens nuevos, el precio y la capitalización pueden proceder de un mercado pequeño.' },
  'Confira metodologia e oferta em documentação ou explorador da rede. Capitalização diluída também não mede liquidez disponível para vender nem valor que todos os titulares conseguiriam realizar.': { en: 'Check the methodology and supply in the project documentation or a network explorer. Fully diluted market capitalization also does not measure the liquidity available to sell or the value all holders could realize.', es: 'Consulta la metodología y la oferta en la documentación o en un explorador de la red. La capitalización totalmente diluida tampoco mide la liquidez disponible para vender ni el valor que todos los titulares podrían realizar.' },
  'Volume não é o mesmo que liquidez': { en: 'Volume is not the same as liquidity', es: 'El volumen no es lo mismo que la liquidez' },
  'Em livro de ofertas, spread e profundidade ajudam a estimar impacto. Em pool descentralizado, uma troca depende da liquidez disponível e da fórmula; ordens maiores alteram mais a cotação. Volume passado não garante compradores futuros.': { en: 'In an order book, spread and depth help estimate market impact. In a decentralized pool, a swap depends on available liquidity and the pool formula; larger orders move the quote more. Past volume does not guarantee future buyers.', es: 'En un libro de órdenes, el spread y la profundidad ayudan a estimar el impacto. En un pool descentralizado, un intercambio depende de la liquidez disponible y de la fórmula; las órdenes mayores alteran más la cotización. El volumen pasado no garantiza compradores futuros.' },
  'Considere slippage, taxas de rede, concentração e quem controla posições de liquidez. Entenda se ela pode ser retirada e por quem. Imagens de “liquidez travada” sem fonte verificável não bastam.': { en: 'Consider slippage, network fees, concentration, and who controls liquidity positions. Find out whether and by whom that liquidity can be withdrawn. Images claiming “locked liquidity” are not enough without a verifiable source.', es: 'Ten en cuenta el slippage, las comisiones de red, la concentración y quién controla las posiciones de liquidez. Averigua si se puede retirar y quién puede hacerlo. Las imágenes que afirman que la “liquidez está bloqueada” no bastan sin una fuente verificable.' },
  'Distribuição e controles do token': { en: 'Token distribution and controls', es: 'Distribución y controles del token' },
  'Investigue concentração de carteiras e cronograma de desbloqueios, distinguindo equipe, pools e custódia quando possível. Exploradores mostram atividade pública, mas identidade e intenção de uma carteira podem ser incertas.': { en: 'Investigate wallet concentration and vesting schedules, distinguishing the team, pools, and custodians where possible. Explorers show public activity, but a wallet’s identity and intent may be uncertain.', es: 'Investiga la concentración de billeteras y los calendarios de desbloqueo, distinguiendo al equipo, los pools y la custodia cuando sea posible. Los exploradores muestran actividad pública, pero la identidad y la intención de una billetera pueden ser inciertas.' },
  'Padrões e redes podem oferecer emissão, congelamento, pausa ou delegação administrativa. Solana Token-2022, por exemplo, tem extensões opcionais; isso não se aplica automaticamente a todo token ou blockchain. Leia as permissões do contrato específico.': { en: 'Token standards and networks may offer minting, freezing, pausing, or administrative delegation. Solana Token-2022, for example, has optional extensions; these do not automatically apply to every token or blockchain. Read the permissions of the specific contract.', es: 'Los estándares y redes pueden permitir la emisión, congelación, pausa o delegación administrativa. Solana Token-2022, por ejemplo, ofrece extensiones opcionales; no se aplican automáticamente a todos los tokens o blockchains. Lee los permisos del contrato específico.' },
  'Verificação e auditoria não são garantia': { en: 'Verification and audits are not guarantees', es: 'La verificación y las auditorías no son una garantía' },
  'Código verificado facilita comparar fonte publicada com bytecode em certas redes, mas não prova segurança, confiança da equipe ou liquidez. Auditorias têm escopo, versão e data; alterações posteriores podem mudar o risco.': { en: 'Verified source code makes it easier to compare published code with bytecode on some networks, but it does not prove security, team trustworthiness, or liquidity. Audits have a defined scope, version, and date; later changes may alter the risk.', es: 'El código verificado facilita comparar el código fuente publicado con el bytecode en algunas redes, pero no demuestra seguridad, confiabilidad del equipo ni liquidez. Las auditorías tienen un alcance, una versión y una fecha; los cambios posteriores pueden modificar el riesgo.' },
  'Contratos, oráculos e bridges introduzem dependências e possíveis falhas. Ferramentas automáticas erram para os dois lados. Trate resultados como pistas de investigação, não certificado.': { en: 'Contracts, oracles, and bridges introduce dependencies and possible failure points. Automated tools can produce false positives and false negatives. Treat their results as leads for further investigation, not as certification.', es: 'Los contratos, oráculos y bridges introducen dependencias y posibles fallos. Las herramientas automatizadas pueden equivocarse en ambos sentidos. Considera sus resultados pistas para investigar, no una certificación.' },
  'Checklist sem promessa de segurança': { en: 'A checklist without promises of safety', es: 'Lista de comprobación sin promesas de seguridad' },
  'Registre endereço e rede oficiais, oferta, concentração e desbloqueios, liquidez e mercado, permissões administrativas, código e auditoria, bridges e oráculos, documentação e cenário de perda total. Não conecte carteira a uma página suspeita para “reivindicar” tokens.': { en: 'Record the official address and network, supply, concentration and unlocks, liquidity and market, admin permissions, code and audit, bridges and oracles, documentation, and a total-loss scenario. Do not connect a wallet to a suspicious page to “claim” tokens.', es: 'Anota la dirección y la red oficiales, la oferta, la concentración y los desbloqueos, la liquidez y el mercado, los permisos administrativos, el código y la auditoría, los bridges y oráculos, la documentación y un escenario de pérdida total. No conectes tu billetera a una página sospechosa para “reclamar” tokens.' },
  'O checklist organiza perguntas, mas não elimina fraude ou perda. Memecoins podem ter volatilidade extrema e dados incompletos. Use a calculadora de risco para um cenário hipotético; pontuação automática não é autorização para comprar.': { en: 'The checklist organizes questions but cannot eliminate fraud or loss. Memecoins can be extremely volatile and have incomplete data. Use the risk calculator for a hypothetical scenario; an automated score is not authorization to buy.', es: 'La lista organiza las preguntas, pero no elimina el fraude ni las pérdidas. Las memecoins pueden tener una volatilidad extrema y datos incompletos. Usa la calculadora de riesgo para un escenario hipotético; una puntuación automática no es una autorización para comprar.' },
  'DeFi: smart contracts, bridges e oráculos explicados': { en: 'DeFi: smart contracts, bridges, and oracles explained', es: 'DeFi: explicación de smart contracts, bridges y oráculos' },
  'Conheça componentes que podem falhar em protocolos DeFi e faça perguntas antes de conectar uma carteira.': { en: 'Learn about components that can fail in DeFi protocols and what to ask before connecting a wallet.', es: 'Conoce los componentes que pueden fallar en los protocolos DeFi y qué preguntar antes de conectar una billetera.' },
  'O que uma aplicação descentralizada automatiza': { en: 'What a decentralized application automates', es: 'Qué automatiza una aplicación descentralizada' },
  'Protocolos DeFi combinam contratos em blockchain, interfaces, ativos, liquidações e às vezes serviços externos. O usuário assina transações. “Descentralizado” não significa ausência de operadores, chaves privilegiadas, dependências ou pontos de falha.': { en: 'DeFi protocols combine blockchain contracts, interfaces, assets, settlement, and sometimes external services. Users sign transactions. “Decentralized” does not mean there are no operators, privileged keys, dependencies, or points of failure.', es: 'Los protocolos DeFi combinan contratos en blockchain, interfaces, activos, liquidaciones y, a veces, servicios externos. El usuario firma las transacciones. “Descentralizado” no significa que no haya operadores, claves privilegiadas, dependencias o puntos de fallo.' },
  'Entenda qual contrato recebe ativos, quem pode alterar parâmetros, como o código é atualizado e quais condições permitem pausar operações.': { en: 'Understand which contract receives assets, who can change its parameters, how the code is upgraded, and under what conditions operations can be paused.', es: 'Entiende qué contrato recibe los activos, quién puede cambiar los parámetros, cómo se actualiza el código y en qué condiciones se pueden pausar las operaciones.' },
  'Contratos executam regras e podem conter falhas': { en: 'Contracts execute rules and may contain flaws', es: 'Los contratos ejecutan reglas y pueden tener fallos' },
  'Bugs, integrações incorretas e permissões mal configuradas podem produzir resultados inesperados. Código imutável dificulta correções; contratos atualizáveis introduzem risco de quem controla a atualização. Código publicado facilita revisão, mas não prova que foi auditado ou está correto.': { en: 'Bugs, faulty integrations, and misconfigured permissions can produce unexpected results. Immutable code is difficult to fix; upgradeable contracts introduce the risk of whoever controls the upgrade. Published code makes review easier, but does not prove it was audited or is correct.', es: 'Los errores, las integraciones defectuosas y los permisos mal configurados pueden producir resultados inesperados. El código inmutable dificulta las correcciones; los contratos actualizables introducen el riesgo de quien controla la actualización. El código publicado facilita la revisión, pero no demuestra que se haya auditado ni que sea correcto.' },
  'Uma auditoria vale para escopo, versão e data específicos. Verifique endereço, rede e mudanças posteriores. “Auditado” sozinho não é um selo universal.': { en: 'An audit applies to a specific scope, version, and date. Verify the address, network, and subsequent changes. “Audited” is not a universal seal of approval.', es: 'Una auditoría corresponde a un alcance, versión y fecha específicos. Comprueba la dirección, la red y los cambios posteriores. “Auditado” no es un sello universal.' },
  'Oráculos conectam dados externos': { en: 'Oracles connect external data', es: 'Los oráculos conectan datos externos' },
  'Contratos não buscam por conta própria qualquer informação fora da cadeia. Oráculos fornecem dados como preços; a segurança depende da origem, atualização, disponibilidade e modelo de confiança. Dados errados ou atrasados podem levar a empréstimos ou liquidações inadequados.': { en: 'Contracts do not independently retrieve arbitrary off-chain information. Oracles provide data such as prices; security depends on its source, freshness, availability, and trust model. Incorrect or delayed data can lead to improper lending or liquidations.', es: 'Los contratos no obtienen por sí mismos cualquier información fuera de la cadena. Los oráculos proporcionan datos como precios; la seguridad depende de la fuente, la actualización, la disponibilidad y el modelo de confianza. Los datos incorrectos o tardíos pueden provocar préstamos o liquidaciones inadecuados.' },
  'Pergunte quantas fontes entram no preço, limites de movimento, atraso e resposta a falhas. Uma rede descentralizada de oráculos reduz algumas dependências, mas não torna qualquer dado infalível.': { en: 'Ask how many sources feed the price, what movement limits apply, how delays are handled, and how failures are addressed. A decentralized oracle network reduces some dependencies, but does not make every data point infallible.', es: 'Pregunta cuántas fuentes alimentan el precio, qué límites de movimiento se aplican, cómo se gestionan los retrasos y cómo se responde a los fallos. Una red descentralizada de oráculos reduce algunas dependencias, pero no vuelve infalible cualquier dato.' },
  'Bridges adicionam novas dependências': { en: 'Bridges add new dependencies', es: 'Los bridges añaden nuevas dependencias' },
  'Uma bridge pode bloquear, queimar, emitir ou liberar representações entre redes. O ativo recebido pode depender de contratos, validadores, multisig, custodiantes ou relayers. Um token wrapped traz risco do mecanismo que afirma lastreá-lo.': { en: 'A bridge may lock, burn, mint, or release representations across networks. The asset you receive may depend on contracts, validators, multisigs, custodians, or relayers. A wrapped token carries the risk of the mechanism claiming to back it.', es: 'Un bridge puede bloquear, quemar, emitir o liberar representaciones entre redes. El activo recibido puede depender de contratos, validadores, multisig, custodios o relayers. Un token wrapped conlleva el riesgo del mecanismo que afirma respaldarlo.' },
  'Confirme rota e ativo oficiais, quem valida mensagens, como fundos são protegidos e o processo em caso de falha. Não escolha uma bridge apenas pela taxa exibida.': { en: 'Confirm the official route and asset, who validates messages, how funds are protected, and what happens if something fails. Do not choose a bridge based only on its displayed fee.', es: 'Confirma la ruta y el activo oficiales, quién valida los mensajes, cómo se protegen los fondos y qué ocurre si hay un fallo. No elijas un bridge solo por la comisión que muestra.' },
  'Revise antes de assinar': { en: 'Review before signing', es: 'Revisa antes de firmar' },
  'Confira domínio, rede, contrato, token, valor, permissões e ação solicitada. Teste quantia pequena quando apropriado. Não compartilhe chave ou frase-semente com suporte, analistas ou serviços de recuperação.': { en: 'Check the domain, network, contract, token, amount, permissions, and requested action. Test with a small amount when appropriate. Do not share a key or seed phrase with support, analysts, or recovery services.', es: 'Comprueba el dominio, la red, el contrato, el token, el importe, los permisos y la acción solicitada. Cuando corresponda, haz una prueba con una cantidad pequeña. No compartas claves ni la frase semilla con soporte, analistas o servicios de recuperación.' },
  'Considere perda de paridade, liquidação, congestionamento, governança, exploit e indisponibilidade da interface. Este checklist organiza questões; não audita um protocolo nem prevê retorno.': { en: 'Consider depegging, liquidation, congestion, governance, exploits, and interface outages. This checklist organizes questions; it does not audit a protocol or predict returns.', es: 'Ten en cuenta la pérdida de paridad, las liquidaciones, la congestión, la gobernanza, los exploits y la falta de disponibilidad de la interfaz. Esta lista organiza preguntas; no audita un protocolo ni predice rendimientos.' },
  'Stablecoins: como funcionam e quais são os riscos': { en: 'Stablecoins: how they work and what the risks are', es: 'Stablecoins: cómo funcionan y cuáles son sus riesgos' },
  'Entenda lastro, resgate, perda de paridade e por que um dólar digital não significa risco zero.': { en: 'Understand backing, redemption, loss of peg, and why a digital dollar does not mean zero risk.', es: 'Comprende el respaldo, el canje, la pérdida de paridad y por qué un dólar digital no significa riesgo cero.' },
  'O que uma stablecoin tenta manter estável': { en: 'What a stablecoin aims to keep stable', es: 'Qué intenta mantener estable una stablecoin' },
  'Stablecoin é um criptoativo projetado para acompanhar uma referência, frequentemente uma moeda como o dólar. Esse objetivo não garante paridade permanente. Há modelos com reservas, criptoativos como garantia, mecanismos algorítmicos ou combinações, cada um com riscos diferentes.': { en: 'A stablecoin is a crypto asset designed to track a reference, often a currency such as the US dollar. This goal does not guarantee a permanent peg. Models may use reserves, crypto collateral, algorithmic mechanisms, or combinations, each with different risks.', es: 'Una stablecoin es un criptoactivo diseñado para seguir una referencia, a menudo una moneda como el dólar. Este objetivo no garantiza una paridad permanente. Hay modelos basados en reservas, criptoactivos como garantía, mecanismos algorítmicos o combinaciones, cada uno con riesgos distintos.' },
  'Identifique emissor ou protocolo, ativo de referência, rede, mecanismo de emissão e resgate, direitos do titular e onde há liquidez. Um ticker parecido em outra rede pode ser um ativo diferente ou uma representação sem relação com o emissor conhecido.': { en: 'Identify the issuer or protocol, reference asset, network, issuance and redemption mechanism, holder rights, and where liquidity exists. A similar ticker on another network may be a different asset or a representation unrelated to the known issuer.', es: 'Identifica al emisor o protocolo, el activo de referencia, la red, el mecanismo de emisión y canje, los derechos del titular y dónde existe liquidez. Un ticker parecido en otra red puede ser un activo distinto o una representación sin relación con el emisor conocido.' },
  'Reservas e direito de resgate importam': { en: 'Reserves and redemption rights matter', es: 'Las reservas y los derechos de canje importan' },
  'Em modelos lastreados por reservas, confiança depende da composição, custódia, liquidez e disponibilidade dos ativos, além das regras de resgate. O FMI discute conexões entre stablecoins, ativos líquidos e mercados financeiros; isso não significa que todas tenham o mesmo lastro ou que qualquer usuário possa resgatar diretamente.': { en: 'For reserve-backed models, trust depends on the assets’ composition, custody, liquidity, and availability, as well as redemption rules. The IMF discusses links between stablecoins, liquid assets, and financial markets; this does not mean all stablecoins have the same backing or that every user can redeem directly.', es: 'En los modelos respaldados por reservas, la confianza depende de la composición, custodia, liquidez y disponibilidad de los activos, además de las reglas de canje. El FMI analiza los vínculos entre stablecoins, activos líquidos y mercados financieros; esto no significa que todas tengan el mismo respaldo ni que cualquier usuario pueda canjearlas directamente.' },
  'Leia relatórios e termos: quem pode resgatar, mínimos, prazos, jurisdição e eventos que suspendem o serviço. Atestados têm escopo e data; não respondem automaticamente a questões de passivos, segregação e operação.': { en: 'Read the reports and terms: who can redeem, minimums, timelines, jurisdiction, and events that suspend the service. Attestations have a scope and date; they do not automatically answer questions about liabilities, segregation, or operations.', es: 'Lee los informes y las condiciones: quién puede canjear, mínimos, plazos, jurisdicción y eventos que suspenden el servicio. Los informes de atestación tienen un alcance y una fecha; no responden automáticamente a cuestiones sobre pasivos, segregación y operaciones.' },
  'A paridade pode falhar': { en: 'The peg can fail', es: 'La paridad puede fallar' },
  'Em momentos de estresse, a cotação pode se afastar da referência. Dúvidas sobre reservas, interrupção de resgates, congestionamento, liquidez concentrada ou falha algorítmica são fatores possíveis. Uma cotação exibida não garante conversão de qualquer quantidade naquele valor.': { en: 'During periods of stress, the price may deviate from its reference. Concerns about reserves, suspended redemptions, congestion, concentrated liquidity, or algorithmic failure may all contribute. A displayed quote does not guarantee that any amount can be converted at that price.', es: 'En momentos de tensión, la cotización puede alejarse de su referencia. Las dudas sobre las reservas, la interrupción de los canjes, la congestión, la liquidez concentrada o un fallo algorítmico pueden influir. Una cotización mostrada no garantiza que cualquier cantidad pueda convertirse a ese precio.' },
  'O preço varia por rede, exchange e par. Confirme o contrato selecionado. Se uma aplicação usa stablecoin como garantia, entenda o que acontece com empréstimos e liquidações se a cotação cair.': { en: 'Price varies by network, exchange, and trading pair. Confirm the selected contract. If an application uses a stablecoin as collateral, understand what happens to loans and liquidations if its price falls.', es: 'El precio varía según la red, el exchange y el par. Confirma el contrato seleccionado. Si una aplicación utiliza una stablecoin como garantía, entiende qué sucede con los préstamos y las liquidaciones si baja su cotización.' },
  'Custódia, rede e contrato também têm riscos': { en: 'Custody, networks, and contracts also carry risks', es: 'La custodia, la red y los contratos también implican riesgos' },
  'Mesmo mantendo paridade, existem riscos de custódia, bloqueio, perda de chave, falha de contrato, ponte entre redes, endereço incorreto e interrupção de serviços. Autocustódia e custódia de terceiros distribuem responsabilidades de formas diferentes.': { en: 'Even if the peg holds, risks remain: custody, freezes, lost keys, contract failures, cross-network bridges, incorrect addresses, and service outages. Self-custody and third-party custody assign responsibilities differently.', es: 'Incluso si mantiene la paridad, existen riesgos de custodia, bloqueo, pérdida de claves, fallos de contratos, puentes entre redes, direcciones incorrectas e interrupciones del servicio. La autocustodia y la custodia de terceros distribuyen las responsabilidades de forma distinta.' },
  'Confirme a rede e o endereço antes de transferir. Ao conectar uma carteira, leia permissões. Nunca forneça frase-semente ou chave privada. Uma stablecoin não elimina phishing nem garante a recuperação de transferência incorreta.': { en: 'Confirm the network and address before transferring. Review permissions when connecting a wallet. Never share your seed phrase or private key. A stablecoin does not prevent phishing or guarantee recovery from a mistaken transfer.', es: 'Confirma la red y la dirección antes de transferir. Lee los permisos al conectar una billetera. Nunca compartas la frase semilla ni la clave privada. Una stablecoin no evita el phishing ni garantiza recuperar una transferencia equivocada.' },
  'Checklist antes de manter saldo': { en: 'A checklist before holding a balance', es: 'Lista de comprobación antes de mantener un saldo' },
  'Confirme ticker e contrato em fonte oficial, mecanismo de paridade, data das informações sobre reservas, regras reais de resgate, rede, liquidez, custodiante ou contrato envolvido e controles que podem restringir transferências. Proteção e regulação variam por país, entidade e produto; não aplique automaticamente orientação dos Estados Unidos ao Brasil.': { en: 'Confirm the ticker and contract using an official source, the peg mechanism, the date of reserve information, actual redemption rules, network, liquidity, custodian or contract involved, and controls that may restrict transfers. Protections and regulations vary by country, entity, and product; do not automatically apply US guidance to Brazil.', es: 'Confirma el ticker y el contrato en una fuente oficial, el mecanismo de paridad, la fecha de la información sobre reservas, las reglas reales de canje, la red, la liquidez, el custodio o contrato involucrado y los controles que pueden restringir transferencias. La protección y la regulación varían según el país, la entidad y el producto; no apliques automáticamente las pautas de Estados Unidos a Brasil.' },
  'O uso em liquidação de operações cripto não torna uma stablecoin equivalente a depósito bancário ou dinheiro garantido. Este guia explica conceitos e não recomenda ativos.': { en: 'Using a stablecoin to settle crypto trades does not make it equivalent to a bank deposit or guaranteed cash. This guide explains concepts and does not recommend assets.', es: 'El uso de una stablecoin para liquidar operaciones cripto no la convierte en un depósito bancario ni en dinero garantizado. Esta guía explica conceptos y no recomienda activos.' },
  'Como guardar cripto: carteira própria ou corretora?': { en: 'How to store crypto: self-custody wallet or exchange?', es: 'Cómo guardar cripto: ¿billetera propia o exchange?' },
  'Compare autocustódia e custódia de terceiros, entenda chaves privadas e crie uma rotina básica de proteção.': { en: 'Compare self-custody with third-party custody, learn about private keys, and establish a basic security routine.', es: 'Compara la autocustodia con la custodia de terceros, entiende las claves privadas y crea una rutina básica de protección.' },
  'Carteiras gerenciam chaves': { en: 'Wallets manage keys', es: 'Las billeteras gestionan claves' },
  'Uma carteira permite gerenciar chaves que autorizam movimentações registradas na blockchain. O saldo pertence ao estado da rede; o aplicativo ou dispositivo mantém credenciais e prepara assinaturas. Perder o aparelho pode ser diferente de perder a frase de recuperação, mas revelar essa frase pode entregar o controle dos ativos.': { en: 'A wallet lets you manage keys that authorize transactions recorded on a blockchain. Your balance is part of the network state; the app or device stores credentials and prepares signatures. Losing a device is not always the same as losing the recovery phrase, but revealing that phrase can hand over control of your assets.', es: 'Una billetera permite gestionar claves que autorizan movimientos registrados en la blockchain. El saldo forma parte del estado de la red; la aplicación o el dispositivo guarda las credenciales y prepara las firmas. Perder el dispositivo no siempre equivale a perder la frase de recuperación, pero revelar esa frase puede ceder el control de tus activos.' },
  'A SEC explica que carteiras guardam chaves privadas, não criptoativos dentro do aparelho. Endereço público permite receber; chave privada autoriza transações. Nunca publique nem envie chave ou frase-semente.': { en: 'The SEC explains that wallets store private keys, not crypto assets inside the device. A public address lets you receive funds; a private key authorizes transactions. Never publish or send a key or seed phrase.', es: 'La SEC explica que las billeteras guardan claves privadas, no criptoactivos dentro del dispositivo. Una dirección pública permite recibir; una clave privada autoriza transacciones. Nunca publiques ni envíes una clave o frase semilla.' },
  'Autocustódia versus custódia de terceiros': { en: 'Self-custody versus third-party custody', es: 'Autocustodia frente a custodia de terceros' },
  'Na autocustódia, você controla as chaves e assume backup, acesso e segurança. Isso reduz dependência de uma corretora, mas erros ou perda da frase podem tornar fundos inacessíveis. Carteiras conectadas à internet são convenientes e mais expostas a ameaças digitais.': { en: 'With self-custody, you control the keys and are responsible for backups, access, and security. This reduces reliance on an exchange, but mistakes or a lost phrase may make funds inaccessible. Internet-connected wallets are convenient and more exposed to digital threats.', es: 'Con la autocustodia, controlas las claves y asumes la responsabilidad de las copias de seguridad, el acceso y la protección. Esto reduce la dependencia de un exchange, pero los errores o la pérdida de la frase pueden dejar los fondos inaccesibles. Las billeteras conectadas a Internet son prácticas, pero están más expuestas a amenazas digitales.' },
  'Com custódia de terceiros, uma corretora ou prestador controla as chaves operacionais. É importante entender solvência, acesso, termos, taxas, segurança e procedimentos em caso de falha. Pesquise se o provedor usa os ativos como garantia ou os mantém segregados.': { en: 'With third-party custody, an exchange or provider controls the operational keys. Understand its solvency, access, terms, fees, security, and failure procedures. Find out whether the provider uses assets as collateral or keeps them segregated.', es: 'Con la custodia de terceros, un exchange o proveedor controla las claves operativas. Es importante entender su solvencia, acceso, condiciones, comisiones, seguridad y procedimientos ante fallos. Averigua si el proveedor utiliza los activos como garantía o los mantiene segregados.' },
  'Proteja frase de recuperação e conta': { en: 'Protect your recovery phrase and account', es: 'Protege tu frase de recuperación y tu cuenta' },
  'Guarde a frase conforme instruções oficiais do dispositivo, protegida de acesso indevido e danos físicos. Fotos, nuvem, chats e arquivos podem criar cópias expostas. A solução adequada depende do modelo de ameaça e do suporte da carteira.': { en: 'Store the phrase according to the device’s official instructions, protected from unauthorized access and physical damage. Photos, cloud storage, chats, and files can create exposed copies. The right approach depends on your threat model and wallet support.', es: 'Guarda la frase siguiendo las instrucciones oficiales del dispositivo y protégela del acceso no autorizado y los daños físicos. Las fotos, la nube, los chats y los archivos pueden crear copias expuestas. La solución adecuada depende del modelo de amenazas y de las opciones de la billetera.' },
  'Desconfie de suporte que pede frase-semente. Golpistas usam falsos airdrops, anúncios e páginas de atendimento. Confirme o domínio por canal confiável e não assine uma transação que não entende.': { en: 'Be wary of support agents who ask for your seed phrase. Scammers use fake airdrops, ads, and support pages. Verify the domain through a trusted channel, and do not sign a transaction you do not understand.', es: 'Desconfía del soporte que te pide la frase semilla. Los estafadores utilizan airdrops, anuncios y páginas de asistencia falsos. Confirma el dominio mediante un canal confiable y no firmes una transacción que no entiendas.' },
  'Teste a transferência e confira a rede': { en: 'Test the transfer and check the network', es: 'Prueba la transferencia y comprueba la red' },
  'Confirme endereço, rede e ativo antes de enviar. Ativos com o mesmo nome podem ter contratos distintos; selecionar uma rede incompatível pode causar perda ou recuperação complexa. Quando apropriado, faça uma transferência pequena de teste e confira o recebimento.': { en: 'Confirm the address, network, and asset before sending. Assets with the same name may have different contracts; choosing an incompatible network can cause loss or make recovery difficult. When appropriate, send a small test transfer and confirm it arrives.', es: 'Confirma la dirección, la red y el activo antes de enviar. Los activos con el mismo nombre pueden tener contratos distintos; elegir una red incompatible puede provocar pérdidas o dificultar la recuperación. Cuando corresponda, haz una transferencia de prueba pequeña y confirma que llegue.' },
  'Ative autenticação multifator, proteja e-mail e telefone, use senhas únicas e mantenha software atualizado. Senha forte não elimina engenharia social ou sessão comprometida.': { en: 'Enable multi-factor authentication, secure your email and phone, use unique passwords, and keep software updated. A strong password does not prevent social engineering or a compromised session.', es: 'Activa la autenticación multifactor, protege tu correo y teléfono, usa contraseñas únicas y mantén el software actualizado. Una contraseña segura no evita la ingeniería social ni una sesión comprometida.' },
  'Escolha conforme responsabilidades que pode cumprir': { en: 'Choose based on the responsibilities you can handle', es: 'Elige según las responsabilidades que puedas asumir' },
  'Compare conveniência, controle, contraparte, recuperação, custos e procedimento de emergência. Nenhuma opção remove todos os riscos. Para valores relevantes, leia a documentação e teste a restauração sem revelar segredos.': { en: 'Compare convenience, control, counterparty, recovery, costs, and emergency procedures. No option removes every risk. For significant amounts, read the documentation and test recovery without exposing secrets.', es: 'Compara la comodidad, el control, la contraparte, la recuperación, los costos y los procedimientos de emergencia. Ninguna opción elimina todos los riesgos. Si se trata de cantidades importantes, lee la documentación y prueba la restauración sin revelar secretos.' },
  'A plataforma educacional nunca precisa da sua chave ou frase. Este material não recomenda carteira nem custodiante específico.': { en: 'The learning platform never needs your key or recovery phrase. This material does not recommend any specific wallet or custodian.', es: 'La plataforma educativa nunca necesita tu clave ni tu frase de recuperación. Este material no recomienda ninguna billetera o custodio en particular.' },
  'Como ler o mercado cripto hoje: preço, liquidez e contexto': { en: 'How to read the crypto market today: price, liquidity, and context', es: 'Cómo leer hoy el mercado cripto: precio, liquidez y contexto' },
  'Um roteiro para interpretar o mercado sem depender de um indicador isolado nem confundir dados com previsões.': { en: 'A guide to interpreting the market without relying on a single indicator or confusing data with forecasts.', es: 'Una guía para interpretar el mercado sin depender de un solo indicador ni confundir datos con pronósticos.' },
  'Defina ativo, unidade e período': { en: 'Define the asset, unit, and timeframe', es: 'Define el activo, la unidad y el período' },
  '“O mercado está subindo?” depende do ativo, da moeda de cotação e do período observado. Bitcoin em reais pode se mover de forma diferente de BTC em dólares por causa do câmbio. Antes de comparar, defina ativo, par, intervalo e se está olhando preço à vista ou contrato futuro. Não misture uma janela de uma hora com uma conclusão sobre ciclos de anos.': { en: '“Is the market going up?” depends on the asset, quote currency, and timeframe. Bitcoin priced in reais may move differently from BTC priced in US dollars because of exchange rates. Before comparing, define the asset, pair, interval, and whether you are looking at spot or futures. Do not use a one-hour window to draw conclusions about multi-year cycles.', es: '“¿Está subiendo el mercado?” depende del activo, la moneda de cotización y el período observado. Bitcoin en reales puede moverse de forma distinta a BTC en dólares por el tipo de cambio. Antes de comparar, define el activo, el par, el intervalo y si observas el precio spot o un contrato de futuros. No mezcles una ventana de una hora con conclusiones sobre ciclos de varios años.' },
  'Uma fotografia de mercado envelhece rápido. Confira horário, fonte, unidade e atraso do dado. Este guia ensina um método de leitura em vez de congelar uma cotação que deixaria de ser atual. Um painel ao vivo deve identificar a fonte e a hora da última atualização.': { en: 'A market snapshot becomes outdated quickly. Check the timestamp, source, unit, and data delay. This guide teaches a way to read markets instead of freezing a quote that would soon be stale. A live dashboard should identify its source and the time of its latest update.', es: 'Una instantánea del mercado queda desactualizada rápidamente. Comprueba la hora, la fuente, la unidad y el retraso de los datos. Esta guía enseña un método de lectura en lugar de fijar una cotización que pronto quedaría obsoleta. Un panel en vivo debe indicar la fuente y la hora de la última actualización.' },
  'Preço, volume e liquidez medem coisas diferentes': { en: 'Price, volume, and liquidity measure different things', es: 'El precio, el volumen y la liquidez miden cosas distintas' },
  'Preço registra uma negociação ou uma referência definida pela plataforma. Volume soma negócios numa janela. Liquidez descreve a facilidade de executar uma ordem sem deslocar demais o preço. Um mercado pode ter volume agregado alto e pouca profundidade perto da cotação em um par ou exchange específicos.': { en: 'Price records a trade or a reference defined by the platform. Volume sums trades over a time window. Liquidity describes how easily an order can execute without moving the price too much. A market may have high aggregate volume but little depth near the quote on a specific pair or exchange.', es: 'El precio registra una operación o una referencia definida por la plataforma. El volumen suma las operaciones de un período. La liquidez describe la facilidad de ejecutar una orden sin mover demasiado el precio. Un mercado puede tener un volumen agregado alto y poca profundidad cerca de la cotización en un par o exchange específico.' },
  'Observe spread entre melhor compra e venda, profundidade disponível e tamanho da ordem considerada. Slippage é a diferença entre preço esperado e executado. Agregadores podem combinar bolsas, moedas e janelas diferentes; o agregado não garante execução numa plataforma específica.': { en: 'Check the spread between the best bid and ask, available depth, and the order size you have in mind. Slippage is the difference between expected and executed price. Aggregators may combine exchanges, currencies, and time windows; the aggregate does not guarantee execution on a specific platform.', es: 'Observa el spread entre la mejor compra y venta, la profundidad disponible y el tamaño de la orden prevista. El slippage es la diferencia entre el precio esperado y el ejecutado. Los agregadores pueden combinar exchanges, monedas y períodos distintos; el agregado no garantiza la ejecución en una plataforma específica.' },
  'Derivativos acrescentam contexto, não uma seta': { en: 'Derivatives add context, not a directional arrow', es: 'Los derivados aportan contexto, no una señal direccional' },
  'Funding em contratos perpétuos é um pagamento periódico entre os lados do contrato conforme suas regras. Open interest contabiliza contratos em aberto; volume conta contratos negociados na janela. Nenhum dos dois informa sozinho se “dinheiro novo está entrando para comprar” ou prevê a direção seguinte.': { en: 'Funding on perpetual contracts is a periodic payment between the two sides of the contract under its rules. Open interest counts open contracts; volume counts contracts traded during the window. Neither metric alone tells you whether “new money is coming in to buy” or predicts the next direction.', es: 'El funding en contratos perpetuos es un pago periódico entre las partes del contrato según sus reglas. El open interest cuenta los contratos abiertos; el volumen cuenta los contratos negociados durante el período. Ninguna de estas métricas indica por sí sola si “está entrando dinero nuevo para comprar” ni predice la dirección siguiente.' },
  'Taxa, intervalo e parâmetros de funding variam por plataforma e contrato. A documentação da Binance, por exemplo, descreve ajustes e regras específicos do produto. Compare fonte, mercado e horário antes de tirar conclusões, e consulte os termos atuais da exchange.': { en: 'Funding rates, intervals, and parameters vary by platform and contract. Binance documentation, for example, describes adjustments and rules specific to its product. Compare the source, market, and timestamp before drawing conclusions, and check the exchange’s current terms.', es: 'La tasa, el intervalo y los parámetros de funding varían según la plataforma y el contrato. La documentación de Binance, por ejemplo, describe ajustes y reglas específicas de su producto. Compara la fuente, el mercado y la hora antes de sacar conclusiones, y consulta las condiciones actuales del exchange.' },
  'Contexto macro e correlação': { en: 'Macro context and correlation', es: 'Contexto macroeconómico y correlación' },
  'Juros, liquidez financeira, câmbio e apetite a risco podem influenciar investidores e coincidir com movimentos em cripto. Correlação observada em um período não prova causalidade, e a relação pode mudar. O FMI discute a conexão crescente entre stablecoins e mercados tradicionais; isso ajuda a formular perguntas, não a prever Bitcoin.': { en: 'Interest rates, financial liquidity, exchange rates, and risk appetite may influence investors and coincide with crypto market moves. Correlation over a given period does not prove causation, and the relationship may change. The IMF discusses growing links between stablecoins and traditional markets; this helps frame questions, not predict Bitcoin.', es: 'Las tasas de interés, la liquidez financiera, los tipos de cambio y el apetito por el riesgo pueden influir en los inversores y coincidir con movimientos de cripto. La correlación observada durante un período no demuestra causalidad, y la relación puede cambiar. El FMI analiza la creciente conexión entre stablecoins y mercados tradicionales; esto ayuda a plantear preguntas, no a predecir Bitcoin.' },
  'Para estudar um evento, anote o que mudou, quando os mercados reagiram e quais explicações alternativas existem. Compare mais de uma janela. Mercados cripto negociam continuamente, mas a reação a um dado macro não é uniforme nem automática.': { en: 'To study an event, note what changed, when markets reacted, and what alternative explanations exist. Compare more than one time window. Crypto markets trade continuously, but reactions to macro data are neither uniform nor automatic.', es: 'Para estudiar un evento, anota qué cambió, cuándo reaccionaron los mercados y qué explicaciones alternativas existen. Compara más de un período. Los mercados cripto operan continuamente, pero la reacción a un dato macroeconómico no es uniforme ni automática.' },
  'Transforme observação em gestão de risco': { en: 'Turn observations into risk management', es: 'Convierte las observaciones en gestión del riesgo' },
  'Registre ativo e par, unidade, fonte e horário, período, spot ou derivativo, volume e profundidade, funding e open interest com suas definições, além da hipótese que quer testar. Se provedores divergem, confira se usam bolsas, moedas ou janelas distintas.': { en: 'Record the asset and pair, unit, source and timestamp, timeframe, spot or derivative market, volume and depth, funding and open interest with their definitions, and the hypothesis you want to test. If providers differ, check whether they use different exchanges, currencies, or windows.', es: 'Registra el activo y el par, la unidad, la fuente y la hora, el período, el mercado spot o de derivados, el volumen y la profundidad, el funding y el open interest con sus definiciones, además de la hipótesis que quieres probar. Si las fuentes difieren, comprueba si utilizan exchanges, monedas o períodos distintos.' },
  'Pergunte o que invalidaria a hipótese e quanto o cenário custaria, incluindo taxas e liquidez. O simulador long/short permite explorar cenários hipotéticos; não recomenda uma operação nem estima uma probabilidade de sucesso.': { en: 'Ask what would invalidate the hypothesis and what the scenario would cost, including fees and liquidity. The long/short simulator lets you explore hypothetical scenarios; it does not recommend a trade or estimate the probability of success.', es: 'Pregunta qué invalidaría la hipótesis y cuánto costaría el escenario, incluidas las comisiones y la liquidez. El simulador long/short permite explorar escenarios hipotéticos; no recomienda operaciones ni estima una probabilidad de éxito.' },
  'Funding rate em cripto: o que significa e como ler': { en: 'Crypto funding rates: what they mean and how to read them', es: 'Funding rate en cripto: qué significa y cómo interpretarlo' },
  'Entenda pagamentos em contratos perpétuos, sinais positivos e negativos e por que funding não é rendimento garantido.': { en: 'Understand payments on perpetual contracts, positive and negative rates, and why funding is not guaranteed income.', es: 'Entiende los pagos en contratos perpetuos, las tasas positivas y negativas, y por qué el funding no es un rendimiento garantizado.' },
  'Por que existe funding': { en: 'Why funding exists', es: 'Por qué existe el funding' },
  'Um contrato perpétuo não tem vencimento como muitos futuros tradicionais. Plataformas usam funding para aproximar seu preço ao preço de referência do ativo à vista. O pagamento ocorre entre participantes comprados e vendidos conforme taxa e calendário do contrato.': { en: 'A perpetual contract has no expiry date, unlike many traditional futures. Platforms use funding to bring its price closer to the spot reference price. Payments pass between long and short participants according to the contract’s rate and schedule.', es: 'Un contrato perpetuo no tiene vencimiento, a diferencia de muchos futuros tradicionales. Las plataformas utilizan el funding para acercar su precio al precio de referencia spot. El pago se transfiere entre participantes long y short según la tasa y el calendario del contrato.' },
  'Na documentação da Binance, funding positivo significa pagamento de posições long para short; taxa negativa inverte o fluxo. Essa convenção é específica do produto. Confira regra, índice e próximo horário de liquidação na exchange usada.': { en: 'In Binance documentation, positive funding means longs pay shorts; a negative rate reverses the flow. This convention is product-specific. Check the rule, index, and next settlement time on the exchange you use.', es: 'En la documentación de Binance, un funding positivo significa que las posiciones long pagan a las short; una tasa negativa invierte el flujo. Esta convención es específica del producto. Consulta la regla, el índice y la próxima hora de liquidación en el exchange que utilices.' },
  'A taxa é uma fotografia, não uma promessa': { en: 'The rate is a snapshot, not a promise', es: 'La tasa es una instantánea, no una promesa' },
  'A taxa exibida pode ser estimativa para a próxima liquidação ou valor realizado, conforme a tela. Ela varia com o prêmio do contrato e outros parâmetros. Fórmulas, intervalos e limites não são universais entre exchanges nem entre todos os símbolos.': { en: 'Depending on the screen, the displayed rate may be an estimate for the next settlement or a realized value. It varies with the contract premium and other parameters. Formulas, intervals, and limits are not universal across exchanges or symbols.', es: 'Según la pantalla, la tasa mostrada puede ser una estimación para la próxima liquidación o un valor realizado. Varía según la prima del contrato y otros parámetros. Las fórmulas, los intervalos y los límites no son universales entre exchanges ni entre todos los símbolos.' },
  'Projetar uma taxa observada por muitos períodos pressupõe que ela permanecerá igual. Essa hipótese pode falhar. Também é preciso considerar valor nominal, frequência, custos de negociação, margem e variação do preço.': { en: 'Projecting an observed rate across many periods assumes it will remain unchanged. That assumption may fail. You must also consider notional value, frequency, trading costs, margin, and price movements.', es: 'Proyectar una tasa observada durante muchos períodos supone que se mantendrá igual. Esa hipótesis puede fallar. También hay que considerar el valor nominal, la frecuencia, los costos de operación, el margen y las variaciones de precio.' },
  'Exemplo didático': { en: 'Illustrative example', es: 'Ejemplo didáctico' },
  'Considere apenas para ilustrar a conta uma posição nominal de 1.000 USDT e funding de 0,01% no próximo período. O valor teórico seria 0,10 USDT. Com taxa positiva, o lado long pagaria ao lado short segundo essa regra. O exemplo não inclui mudanças de posição ou arredondamentos.': { en: 'For illustration only, consider a 1,000 USDT notional position and a 0.01% funding rate for the next interval. The theoretical amount would be 0.10 USDT. Under this rule, with a positive rate, the long side would pay the short side. The example does not include position changes or rounding.', es: 'Solo para ilustrar el cálculo, considera una posición nominal de 1.000 USDT y un funding del 0,01% para el próximo período. El importe teórico sería de 0,10 USDT. Con una tasa positiva, la parte long pagaría a la short según esta regla. El ejemplo no incluye cambios de posición ni redondeos.' },
  'Cada produto define quando a posição precisa estar aberta para participar da liquidação. Uma taxa favorável não elimina uma perda de preço que pode ser muito maior que o pagamento recebido.': { en: 'Each product defines when a position must be open to participate in settlement. A favorable rate does not eliminate a price loss that may be much larger than the payment received.', es: 'Cada producto define cuándo debe estar abierta una posición para participar en la liquidación. Una tasa favorable no elimina una pérdida por precio que puede ser mucho mayor que el pago recibido.' },
  'Taxa alta não prevê reversão': { en: 'A high rate does not predict a reversal', es: 'Una tasa alta no predice un cambio de tendencia' },
  'Taxas extremas podem revelar um custo elevado ou desequilíbrio momentâneo, mas não identificam a intenção de cada participante nem quanto a condição vai durar. O preço pode seguir a tendência, reverter ou ficar lateral. Funding caro, por si só, não é sinal de reversão.': { en: 'Extreme rates may indicate high costs or a temporary imbalance, but they do not reveal each participant’s intent or how long the condition will last. Price may continue the trend, reverse, or move sideways. Expensive funding alone is not a reversal signal.', es: 'Las tasas extremas pueden reflejar costos elevados o un desequilibrio momentáneo, pero no revelan la intención de cada participante ni cuánto durará la situación. El precio puede seguir la tendencia, cambiar de dirección o moverse lateralmente. Un funding caro, por sí solo, no es una señal de reversión.' },
  'Compare taxa estimada e realizada, preço do perpétuo versus índice, open interest, volume e liquidez. Open interest e volume têm definições diferentes e dependem de janela e mercado.': { en: 'Compare the estimated and realized rates, perpetual price versus index, open interest, volume, and liquidity. Open interest and volume have different definitions and depend on the timeframe and market.', es: 'Compara las tasas estimada y realizada, el precio del perpetuo frente al índice, el open interest, el volumen y la liquidez. El open interest y el volumen tienen definiciones distintas y dependen del período y del mercado.' },
  'Custos e margem mudam o resultado': { en: 'Costs and margin change the outcome', es: 'Los costos y el margen cambian el resultado' },
  'Funding pode reduzir saldo disponível e afetar margem segundo as regras da plataforma. Com alavancagem, uma oscilação adversa pode consumir margem e levar à liquidação antes de uma hipótese de longo prazo se realizar. O simulador do site não calcula com precisão as regras de cada exchange.': { en: 'Funding may reduce available balance and affect margin under the platform’s rules. With leverage, an adverse move may consume margin and trigger liquidation before a long-term thesis plays out. The site simulator does not precisely calculate each exchange’s rules.', es: 'El funding puede reducir el saldo disponible y afectar el margen según las reglas de la plataforma. Con apalancamiento, un movimiento adverso puede consumir margen y provocar una liquidación antes de que se cumpla una hipótesis a largo plazo. El simulador del sitio no calcula con precisión las reglas de cada exchange.' },
  'Consulte sempre os parâmetros atuais do contrato. A fonte citada descreve Binance, não todos os mercados. Este artigo é educacional e não recomenda arbitragem ou operação alavancada.': { en: 'Always check the contract’s current parameters. The cited source describes Binance, not every market. This article is educational and does not recommend arbitrage or leveraged trading.', es: 'Consulta siempre los parámetros actuales del contrato. La fuente citada describe Binance, no todos los mercados. Este artículo es educativo y no recomienda arbitraje ni operaciones apalancadas.' },
  'Open interest e volume em cripto: entenda a diferença': { en: 'Open interest and volume in crypto: understand the difference', es: 'Open interest y volumen en cripto: entiende la diferencia' },
  'Saiba o que cada métrica de derivativos contabiliza e por que nenhuma indica sozinha a direção do mercado.': { en: 'Learn what each derivatives metric counts and why neither one indicates market direction on its own.', es: 'Descubre qué contabiliza cada métrica de derivados y por qué ninguna indica por sí sola la dirección del mercado.' },
  'Volume conta atividade na janela': { en: 'Volume counts activity over a time window', es: 'El volumen cuenta la actividad durante un período' },
  'Volume de derivativos conta contratos negociados durante um período. O mesmo contrato pode ser negociado várias vezes, então o volume pode crescer sem aumento proporcional no número de posições ainda abertas. Confira janela, unidade e se a tela mostra contratos ou valor nominal.': { en: 'Derivatives volume counts contracts traded over a period. The same contract may be traded many times, so volume can grow without a proportional increase in the number of positions still open. Check the timeframe, unit, and whether the screen shows contracts or notional value.', es: 'El volumen de derivados cuenta los contratos negociados durante un período. El mismo contrato puede negociarse varias veces, por lo que el volumen puede crecer sin un aumento proporcional del número de posiciones que siguen abiertas. Comprueba el período, la unidad y si la pantalla muestra contratos o valor nominal.' },
  'Provedores podem agregar exchanges e contratos diferentes. Compare ativo, vencimento, unidade e mercados equivalentes. Um valor agregado não mostra necessariamente a profundidade onde sua ordem seria executada.': { en: 'Providers may aggregate different exchanges and contracts. Compare the asset, expiry, unit, and equivalent markets. An aggregate value does not necessarily show the depth where your order would execute.', es: 'Los proveedores pueden agregar distintos exchanges y contratos. Compara el activo, el vencimiento, la unidad y los mercados equivalentes. Un valor agregado no muestra necesariamente la profundidad disponible donde se ejecutaría tu orden.' },
  'Open interest conta contratos que continuam abertos': { en: 'Open interest counts contracts that remain open', es: 'El open interest cuenta los contratos que siguen abiertos' },
  'Open interest é o total de contratos abertos que ainda não foram compensados ou liquidados. Cada contrato tem parte comprada e vendida, mas é contado uma vez. A CME explica essa distinção para seus futuros.': { en: 'Open interest is the total number of open contracts that have not been offset or settled. Each contract has a long and a short side, but it is counted once. CME explains this distinction for its futures.', es: 'El open interest es el total de contratos abiertos que aún no se han compensado ni liquidado. Cada contrato tiene una parte compradora y otra vendedora, pero se cuenta una sola vez. CME explica esta diferencia para sus futuros.' },
  'Aberturas podem aumentar a métrica e encerramentos reduzi-la. Ela não revela identidade, intenção ou qual lado seria “mais forte”. Em cripto, confirme se o dado está em contratos, moeda ou valor equivalente.': { en: 'New positions may increase the metric, while closures may reduce it. It does not reveal identity, intent, or which side is “stronger.” In crypto, confirm whether the data is in contracts, coins, or equivalent value.', es: 'La apertura de posiciones puede aumentar la métrica y su cierre reducirla. No revela la identidad, la intención ni qué lado sería “más fuerte”. En cripto, confirma si el dato se expresa en contratos, monedas o valor equivalente.' },
  'O que as combinações não provam': { en: 'What combinations do not prove', es: 'Qué no demuestran las combinaciones' },
  'Preço subindo com open interest maior indica que mais contratos permanecem abertos durante aquela janela. Não prova que só compradores chegaram: cada contrato tem uma contraparte vendida. Preço caindo com open interest menor tampouco revela quem fechou ou por quê.': { en: 'A rising price with higher open interest means more contracts remained open during that period. It does not prove that only buyers entered: every contract has a short counterparty. A falling price with lower open interest likewise does not reveal who closed positions or why.', es: 'Un precio al alza junto con un mayor open interest indica que quedaron más contratos abiertos durante ese período. No demuestra que solo hayan entrado compradores: cada contrato tiene una contraparte vendedora. Del mismo modo, un precio a la baja con menor open interest no revela quién cerró ni por qué.' },
  'Preço, volume, funding e open interest podem descrever eventos passados quando fonte, período e unidades estão claros. Isoladamente, não fornecem próxima direção nem probabilidade de reversão.': { en: 'Price, volume, funding, and open interest can describe past events when the source, timeframe, and units are clear. On their own, they do not provide the next direction or the probability of a reversal.', es: 'El precio, el volumen, el funding y el open interest pueden describir eventos pasados cuando se conocen la fuente, el período y las unidades. Por sí solos, no indican la dirección siguiente ni la probabilidad de un cambio de tendencia.' },
  'Exemplo hipotético': { en: 'Hypothetical example', es: 'Ejemplo hipotético' },
  'Imagine um contrato com 100 posições abertas no início do dia. Entradas e fechamentos mudam o saldo para 120 contratos ao final. O volume pode registrar várias negociações de entrada, saída e troca entre participantes; não é simplesmente o aumento líquido de 20.': { en: 'Imagine a contract with 100 open positions at the start of the day. Openings and closures bring the total to 120 contracts by the end. Volume may record many entries, exits, and trades between participants; it is not simply the net increase of 20.', es: 'Imagina un contrato con 100 posiciones abiertas al comienzo del día. Las aperturas y cierres dejan un total de 120 contratos al final. El volumen puede registrar muchas operaciones de entrada, salida e intercambio entre participantes; no es simplemente el aumento neto de 20.' },
  'Se um painel informa alta de 20% no open interest, confira mercado e unidade comparados. O valor nominal agregado também pode mudar junto com o preço, mesmo que a quantidade não mude na mesma proporção.': { en: 'If a dashboard reports a 20% rise in open interest, check which markets and units are being compared. Aggregate notional value may also change with price, even when contract count does not change proportionally.', es: 'Si un panel indica un aumento del 20% en el open interest, comprueba qué mercados y unidades se comparan. El valor nominal agregado también puede cambiar junto con el precio, aunque la cantidad no cambie en la misma proporción.' },
  'Use métricas para fazer perguntas melhores': { en: 'Use metrics to ask better questions', es: 'Usa métricas para plantear mejores preguntas' },
  'Pergunte qual mercado e intervalo entram no cálculo, se a métrica é quantidade ou valor e se houve mudança de metodologia. O preço é spot, índice, mark price ou perpétuo? Qual funding e profundidade existem? Anotar isso evita comparar séries diferentes com nomes parecidos.': { en: 'Ask which market and timeframe the calculation uses, whether the metric is quantity or value, and whether the methodology changed. Is the price spot, index, mark, or perpetual? What are the funding and depth? Recording this avoids comparing different series with similar names.', es: 'Pregunta qué mercado y período incluye el cálculo, si la métrica expresa cantidad o valor y si cambió la metodología. ¿El precio es spot, índice, mark o perpetuo? ¿Qué funding y profundidad hay? Anotarlo evita comparar series distintas con nombres parecidos.' },
  'O simulador long/short ajuda a visualizar cenários de preço. Ele não usa open interest e não converte leitura de painel em recomendação.': { en: 'The long/short simulator helps visualize price scenarios. It does not use open interest or turn a dashboard reading into a recommendation.', es: 'El simulador long/short ayuda a visualizar escenarios de precios. No utiliza el open interest ni convierte la lectura de un panel en una recomendación.' },
  'Como calcular stop loss no Bitcoin: veja o risco antes da entrada': { en: 'How to calculate a Bitcoin stop loss: assess risk before entry', es: 'Cómo calcular un stop loss en Bitcoin: evalúa el riesgo antes de entrar' },
  'Entenda distância do stop, perda planejada, execução e relação entre alvo e risco em um exemplo de Bitcoin.': { en: 'Understand stop distance, planned loss, execution, and the reward-to-risk relationship in a Bitcoin example.', es: 'Comprende la distancia del stop, la pérdida prevista, la ejecución y la relación entre objetivo y riesgo con un ejemplo de Bitcoin.' },
  'O stop começa com uma hipótese': { en: 'A stop starts with a hypothesis', es: 'Un stop parte de una hipótesis' },
  'Um stop loss é uma instrução de saída condicionada a um preço. Antes de preencher esse preço, vale escrever qual hipótese está sendo testada e o que faria essa hipótese deixar de fazer sentido. A calculadora mostra a consequência de uma escolha; ela não encontra um ponto de entrada nem determina o melhor stop para o mercado.': { en: 'A stop-loss is an exit instruction triggered by a price. Before entering that price, write down the hypothesis being tested and what would invalidate it. The calculator shows the consequence of a choice; it does not find an entry point or determine the best stop for the market.', es: 'Un stop loss es una instrucción de salida condicionada a un precio. Antes de introducirlo, conviene escribir qué hipótesis se está poniendo a prueba y qué la invalidaría. La calculadora muestra las consecuencias de una elección; no encuentra un punto de entrada ni determina el mejor stop para el mercado.' },
  'Imagine uma compra fictícia de Bitcoin a 300.000 USDT por BTC. Escolher 294.000 USDT como stop coloca a saída planejada 2% abaixo da entrada. Isso descreve a distância no preço do ativo. Ainda falta conhecer a quantidade comprada para descobrir quantos USDT estarão expostos a esse movimento. Todos os valores aqui são educativos e não representam cotação atual.': { en: 'Imagine a hypothetical Bitcoin purchase at 300,000 USDT per BTC. Setting a stop at 294,000 USDT places the planned exit 2% below entry. This describes the distance in the asset’s price. You still need the position size to determine how many USDT are exposed to that move. All figures are educational and are not current quotes.', es: 'Imagina una compra hipotética de Bitcoin a 300.000 USDT por BTC. Fijar el stop en 294.000 USDT sitúa la salida prevista un 2% por debajo de la entrada. Esto describe la distancia en el precio del activo. Aún falta conocer la cantidad comprada para calcular cuántos USDT quedan expuestos a ese movimiento. Todas las cifras son educativas y no representan una cotización actual.' },
  'Transforme distância em perda planejada': { en: 'Turn distance into planned loss', es: 'Convierte la distancia en una pérdida prevista' },
  'Em uma posição linear comprada, a diferença entre entrada e stop é a perda por unidade de BTC. Multiplicar essa diferença pela quantidade produz a perda bruta planejada. A mesa de risco também considera as taxas informadas ao dimensionar a quantidade. Os exemplos deste artigo usam taxas zeradas para isolar a distância do stop. Entrada e stop iguais não permitem dimensionar por essa fórmula.': { en: 'For a linear long position, the difference between entry and stop is the loss per BTC. Multiplying that difference by the position size gives the planned gross loss. The risk calculator also factors in the fees you enter when sizing a position. This article’s examples use zero fees to isolate stop distance. If entry and stop are equal, this formula cannot size the position.', es: 'En una posición long lineal, la diferencia entre la entrada y el stop es la pérdida por cada BTC. Multiplicar esa diferencia por la cantidad da la pérdida bruta prevista. La calculadora de riesgo también tiene en cuenta las comisiones introducidas al calcular la cantidad. Los ejemplos de este artículo utilizan comisiones cero para aislar la distancia del stop. Si la entrada y el stop son iguales, esta fórmula no permite calcular la cantidad.' },
  'Essa conta precisa usar a mesma unidade em todos os valores: os preços são USDT por BTC e a banca é USDT. Misturar preços em reais com banca em USDT sem conversão produz um cálculo inconsistente. USDT é a unidade do modelo, sem equivalência automática com reais ou dólares. Também é importante separar exposição da perda planejada.': { en: 'This calculation must use consistent units: prices are in USDT per BTC, and capital is in USDT. Mixing prices in reais with capital in USDT without converting produces an inconsistent result. USDT is the model’s unit and is not automatically equivalent to reais or US dollars. It is also important to distinguish exposure from planned loss.', es: 'Este cálculo debe utilizar las mismas unidades: los precios se expresan en USDT por BTC y el capital, en USDT. Mezclar precios en reales con capital en USDT sin convertirlos produce un cálculo incoherente. USDT es la unidad del modelo y no equivale automáticamente a reales o dólares. También es importante distinguir la exposición de la pérdida prevista.' },
  'Gatilho não é preço garantido': { en: 'A trigger is not a guaranteed price', es: 'El precio de activación no es un precio garantizado' },
  'No stop a mercado, atingir o gatilho normalmente envia uma ordem a mercado. No stop limitado, o gatilho ativa uma ordem limitada, que pode ficar sem execução. A FINRA explica essa diferença no contexto de ações; no mercado cripto, é necessário verificar como a plataforma implementa cada ordem, inclusive qual preço dispara o gatilho.': { en: 'With a stop-market order, reaching the trigger usually submits a market order. With a stop-limit, the trigger activates a limit order that may not execute. FINRA explains this distinction for stocks; in crypto, check how the platform implements each order, including which price triggers it.', es: 'Con un stop de mercado, alcanzar el precio de activación suele enviar una orden de mercado. Con un stop límite, el precio de activación activa una orden límite que podría no ejecutarse. FINRA explica esta diferencia para las acciones; en cripto, comprueba cómo implementa cada orden la plataforma, incluido qué precio activa el stop.' },
  'A diferença entre preço esperado e preço executado é chamada de slippage. Uma saída pior que a simulada aumenta a perda; taxas de entrada e saída também alteram o total. Esses efeitos são particularmente relevantes quando a liquidez é baixa ou o preço muda rapidamente.': { en: 'The difference between expected and executed price is called slippage. An exit worse than the one simulated increases the loss; entry and exit fees also change the total. These effects matter especially when liquidity is low or prices move quickly.', es: 'La diferencia entre el precio esperado y el ejecutado se llama slippage. Una salida peor que la simulada aumenta la pérdida; las comisiones de entrada y salida también modifican el total. Estos efectos son especialmente importantes cuando la liquidez es baja o el precio cambia rápidamente.' },
  'O alvo não informa a chance de sucesso': { en: 'A target does not tell you the chance of success', es: 'El objetivo no indica la probabilidad de éxito' },
  'Com alvo em 312.000 USDT, o ganho bruto do exemplo seria 120 USDT: duas vezes o risco bruto de 60 USDT. A relação potencial é 2:1. Isso compara duas distâncias; não significa que o alvo será atingido nem que a operação tem vantagem estatística.': { en: 'With a target of 312,000 USDT, the example’s gross gain would be 120 USDT: twice the gross risk of 60 USDT. The potential ratio is 2:1. This compares two distances; it does not mean the target will be reached or that the trade has a statistical edge.', es: 'Con un objetivo de 312.000 USDT, la ganancia bruta del ejemplo sería de 120 USDT: el doble del riesgo bruto de 60 USDT. La relación potencial es de 2:1. Esto compara dos distancias; no significa que se alcance el objetivo ni que la operación tenga una ventaja estadística.' },
  'Para avaliar uma sequência de operações, também seriam necessários resultados observados, frequência de acertos, perdas efetivas e custos. Alterar o alvo apenas para deixar a relação mais bonita não fornece evidência sobre a probabilidade de execução.': { en: 'Evaluating a series of trades would also require observed results, win rate, actual losses, and costs. Changing the target just to make the ratio look better provides no evidence about the probability of execution.', es: 'Para evaluar una serie de operaciones, también harían falta resultados observados, frecuencia de aciertos, pérdidas efectivas y costos. Cambiar el objetivo solo para que la relación parezca mejor no aporta evidencia sobre la probabilidad de ejecución.' },
  'Experimente mudar uma variável por vez': { en: 'Try changing one variable at a time', es: 'Prueba cambiar una variable a la vez' },
  'Na mesa de risco, mantenha a banca e o risco escolhido e afaste o stop. Observe a quantidade calculada diminuir. Depois aproxime o stop e compare a quantidade e a exposição derivadas. Para estudar uma quantidade fixa, use o simulador long/short e varie a saída. Esses exercícios ajudam a perceber por que distância de saída e tamanho precisam ser considerados juntos.': { en: 'In the risk calculator, keep capital and selected risk fixed, then move the stop farther away. Notice the calculated position size decrease. Next, move the stop closer and compare the resulting size and exposure. To study a fixed position size, use the long/short simulator and vary the exit. These exercises show why exit distance and position size must be considered together.', es: 'En la calculadora de riesgo, mantén fijo el capital y el riesgo elegido, y aleja el stop. Observa cómo disminuye la cantidad calculada. Después, acerca el stop y compara la cantidad y la exposición resultantes. Para estudiar una cantidad fija, usa el simulador long/short y cambia la salida. Estos ejercicios ayudan a entender por qué la distancia de salida y el tamaño deben considerarse conjuntamente.' },
  'O resultado é um cenário simplificado, não uma ordem enviada à corretora. Ele não prevê gaps, liquidação, indisponibilidade do serviço ou execução parcial. Use a ferramenta para entender a aritmética e avance para a aula de gestão de risco para discutir as decisões que a conta não resolve.': { en: 'The result is a simplified scenario, not an order sent to an exchange. It does not predict gaps, liquidation, service outages, or partial execution. Use the tool to understand the arithmetic, then continue to the risk-management lesson to discuss decisions the calculation cannot resolve.', es: 'El resultado es un escenario simplificado, no una orden enviada al exchange. No predice gaps, liquidaciones, interrupciones del servicio ni ejecuciones parciales. Usa la herramienta para entender la aritmética y continúa con la clase de gestión del riesgo para analizar las decisiones que el cálculo no resuelve.' },
  'Quanto comprar? Entenda o tamanho da posição em cripto': { en: 'How much to buy? Understand crypto position sizing', es: '¿Cuánto comprar? Entiende el tamaño de una posición en cripto' },
  'Separe banca, exposição e risco e descubra por que mudar o stop altera a quantidade em uma simulação.': { en: 'Separate capital, exposure, and risk, and see why changing a stop changes position size in a simulation.', es: 'Distingue el capital, la exposición y el riesgo, y descubre por qué cambiar el stop modifica la cantidad en una simulación.' },
  'Três números que não são equivalentes': { en: 'Three numbers that are not equivalent', es: 'Tres cifras que no son equivalentes' },
  'Banca é o capital usado como referência no exercício. Exposição é o valor representado pela posição no preço de entrada. Risco planejado é a perda estimada se a saída ocorrer no stop informado. Dizer “vou usar 2.000 USDT” não revela qual desses números está sendo descrito, e essa confusão muda completamente a interpretação do cenário.': { en: 'Capital is the amount used as a reference in the exercise. Exposure is the position’s value at the entry price. Planned risk is the estimated loss if the exit occurs at the stated stop. Saying “I will use 2,000 USDT” does not tell us which of these figures you mean, and that confusion changes how the scenario should be interpreted.', es: 'El capital es la cantidad utilizada como referencia en el ejercicio. La exposición es el valor de la posición al precio de entrada. El riesgo previsto es la pérdida estimada si la salida se produce en el stop indicado. Decir “voy a usar 2.000 USDT” no aclara cuál de estas cifras se describe, y esa confusión cambia por completo la interpretación del escenario.' },
  'Em uma compra spot sem financiamento, a exposição costuma corresponder ao valor pago pelo ativo antes das taxas. Em derivativos, uma margem menor pode sustentar uma exposição maior. Por isso, a quantidade não deve ser confundida com a margem nem a margem com uma perda máxima garantida.': { en: 'For an unfinanced spot purchase, exposure usually equals the amount paid for the asset before fees. In derivatives, a smaller margin may support a larger exposure. Position size should therefore not be confused with margin, nor should margin be mistaken for a guaranteed maximum loss.', es: 'En una compra spot sin financiación, la exposición suele corresponder al importe pagado por el activo antes de las comisiones. En los derivados, un margen menor puede respaldar una exposición mayor. Por eso no se debe confundir la cantidad con el margen ni el margen con una pérdida máxima garantizada.' },
  'Comece pelo orçamento de risco do exemplo': { en: 'Start with the example’s risk budget', es: 'Empieza con el presupuesto de riesgo del ejemplo' },
  'Sem taxas, dimensionar uma posição linear com stop envolve converter o percentual de risco em dinheiro e dividir pela distância entre entrada e stop. Quantidade = risco em dinheiro ÷ distância por unidade. Na mesa de risco, as taxas informadas também entram no dimensionamento. Os exemplos abaixo usam ambas as taxas zeradas. O percentual é uma hipótese, sem um número universalmente adequado para todas as pessoas.': { en: 'Without fees, sizing a linear position with a stop means converting the risk percentage to a cash amount and dividing it by the distance between entry and stop. Position size = cash risk ÷ distance per unit. The risk calculator also includes the fees you enter. The examples below set both fees to zero. The percentage is an assumption; no single figure is suitable for everyone.', es: 'Sin comisiones, calcular el tamaño de una posición lineal con stop consiste en convertir el porcentaje de riesgo en un importe y dividirlo por la distancia entre la entrada y el stop. Cantidad = riesgo en dinero ÷ distancia por unidad. La calculadora de riesgo también incluye las comisiones indicadas. En los ejemplos siguientes, ambas comisiones son cero. El porcentaje es una hipótesis; no existe una cifra universalmente adecuada para todos.' },
  'A CME apresenta a relação entre stop e risco escolhido como parte do dimensionamento. Aqui usamos valores próprios e uma quantidade fracionária de BTC para tornar a conta visível. Em contratos reais, multiplicador, lote mínimo e passo de quantidade precisam ser respeitados; arredondar para cima pode ultrapassar o orçamento.': { en: 'CME presents the relationship between a stop and chosen risk as part of position sizing. Here we use illustrative values and a fractional BTC amount to make the calculation visible. Real contracts have multipliers, minimum lot sizes, and quantity increments; rounding up may exceed the budget.', es: 'CME presenta la relación entre el stop y el riesgo elegido como parte del cálculo del tamaño de la posición. Aquí usamos valores ilustrativos y una cantidad fraccionaria de BTC para mostrar la operación. Los contratos reales tienen multiplicadores, tamaños mínimos de lote e incrementos de cantidad; redondear hacia arriba puede superar el presupuesto.' },
  'Afaste o stop e compare a quantidade': { en: 'Move the stop farther away and compare position size', es: 'Aleja el stop y compara la cantidad' },
  'Se o stop passa para 288.000 USDT, a distância dobra para 12.000 USDT por BTC. Mantendo o risco bruto em 100 USDT, a quantidade cai para aproximadamente 0,008333 BTC e a exposição para 2.500 USDT. O orçamento de risco permanece igual porque a mudança na quantidade compensa a distância maior.': { en: 'If the stop moves to 288,000 USDT, the distance doubles to 12,000 USDT per BTC. Keeping gross risk at 100 USDT reduces the position size to approximately 0.008333 BTC and exposure to 2,500 USDT. The risk budget stays the same because the smaller position offsets the greater distance.', es: 'Si el stop se mueve a 288.000 USDT, la distancia se duplica a 12.000 USDT por BTC. Al mantener el riesgo bruto en 100 USDT, la cantidad baja a aproximadamente 0,008333 BTC y la exposición a 2.500 USDT. El presupuesto de riesgo se mantiene porque la menor cantidad compensa la mayor distancia.' },
  'Se uma posição já aberta mantiver a quantidade anterior, a perda bruta planejada passaria a aproximadamente 200 USDT. Mover o stop depois da entrada pode ampliar o risco sem depósito novo. Na mesa de risco, porém, a quantidade sempre é recalculada para respeitar o orçamento; ela não representa automaticamente a alteração de uma posição existente.': { en: 'If an already-open position kept its previous size, the planned gross loss would rise to approximately 200 USDT. Moving the stop after entry may increase risk without any new deposit. In the risk calculator, however, position size is recalculated to respect the budget; it does not automatically represent a change to an existing position.', es: 'Si una posición ya abierta mantuviera la cantidad anterior, la pérdida bruta prevista subiría a unos 200 USDT. Mover el stop después de entrar puede aumentar el riesgo sin un nuevo depósito. Sin embargo, en la calculadora de riesgo la cantidad se recalcula para respetar el presupuesto; no representa automáticamente un cambio en una posición existente.' },
  'A conta pode exceder o capital disponível': { en: 'The calculation may exceed available capital', es: 'El cálculo puede superar el capital disponible' },
  'Um stop muito próximo pode gerar uma quantidade grande. Com risco de 100 USDT e distância de apenas 1.000 USDT por BTC, a fórmula retorna 0,1 BTC: 30.000 USDT de exposição na entrada do exemplo. Essa compra não cabe em uma banca de 10.000 USDT no spot sem financiamento.': { en: 'A very close stop can produce a large position size. With 100 USDT of risk and a distance of only 1,000 USDT per BTC, the formula returns 0.1 BTC: 30,000 USDT of exposure at the example’s entry price. That spot purchase would not fit within 10,000 USDT of capital without financing.', es: 'Un stop muy cercano puede generar una cantidad grande. Con un riesgo de 100 USDT y una distancia de solo 1.000 USDT por BTC, la fórmula da 0,1 BTC: 30.000 USDT de exposición al precio de entrada del ejemplo. Esa compra spot no cabe en un capital de 10.000 USDT sin financiación.' },
  'Esse resultado deve ser interpretado como incompatibilidade entre as hipóteses, e não como convite para usar alavancagem. É possível estudar outro orçamento, outra quantidade ou simplesmente descartar o cenário. Aumentar a exposição também altera custos e pode aumentar a dificuldade de execução.': { en: 'Interpret this result as a mismatch between the assumptions, not as an invitation to use leverage. You can study a different budget or position size, or discard the scenario. Increasing exposure also changes costs and may make execution more difficult.', es: 'Este resultado debe interpretarse como una incompatibilidad entre las hipótesis, no como una invitación a utilizar apalancamiento. Puedes estudiar otro presupuesto u otra cantidad, o descartar el escenario. Aumentar la exposición también modifica los costos y puede dificultar la ejecución.' },
  'Considere a posição dentro do conjunto': { en: 'Consider the position as part of the whole', es: 'Considera la posición dentro del conjunto' },
  'Duas operações com risco planejado de 100 USDT cada não equivalem a apenas 100 USDT de risco total. Se ambas forem encerradas no stop, a soma bruta será 200 USDT. Ativos que se movem juntos podem tornar várias posições uma exposição concentrada ao mesmo evento.': { en: 'Two trades with a planned risk of 100 USDT each do not add up to just 100 USDT of total risk. If both close at their stops, the gross total is 200 USDT. Assets that move together can make several positions a concentrated exposure to the same event.', es: 'Dos operaciones con un riesgo previsto de 100 USDT cada una no equivalen a solo 100 USDT de riesgo total. Si ambas se cierran en el stop, la suma bruta será de 200 USDT. Los activos que se mueven juntos pueden concentrar varias posiciones en torno al mismo evento.' },
  'A mesa de risco inclui as taxas de entrada e saída informadas e mostra perda planejada e resultado no alvo após essas taxas. Ela não inclui slippage, funding, liquidação ou outras posições da conta. Registre as hipóteses e compare o resultado com o capital disponível. O objetivo é dar significado à quantidade, sem transformar uma fórmula em promessa de controle absoluto das perdas.': { en: 'The risk calculator includes the entry and exit fees you enter and shows planned loss and target result after those fees. It does not include slippage, funding, liquidation, or other account positions. Record your assumptions and compare the result with available capital. The goal is to make position size meaningful, not turn a formula into a promise of absolute loss control.', es: 'La calculadora de riesgo incluye las comisiones de entrada y salida indicadas y muestra la pérdida prevista y el resultado en el objetivo después de esas comisiones. No incluye slippage, funding, liquidaciones ni otras posiciones de la cuenta. Anota las hipótesis y compara el resultado con el capital disponible. El objetivo es dar sentido a la cantidad, no convertir una fórmula en una promesa de control absoluto de las pérdidas.' },
  'Long ou short: o que muda quando o Bitcoin sobe ou cai?': { en: 'Long or short: what changes when Bitcoin rises or falls?', es: 'Long o short: ¿qué cambia cuando Bitcoin sube o baja?' },
  'Compare os sinais do resultado em posições compradas e vendidas e entenda a diferença entre vender spot e abrir short.': { en: 'Compare the direction of returns on long and short positions, and understand the difference between selling spot and opening a short.', es: 'Compara el signo del resultado en posiciones long y short, y entiende la diferencia entre vender en spot y abrir un short.' },
  'A direção define o sinal do resultado': { en: 'Direction determines the sign of the result', es: 'La dirección determina el signo del resultado' },
  'Uma posição long, ou comprada, tem resultado bruto positivo quando o preço de saída supera o de entrada. Uma posição short, ou vendida, tem resultado bruto positivo quando a saída fica abaixo da entrada. O mesmo movimento pode beneficiar uma direção e prejudicar a outra; nenhuma delas descreve antecipadamente o que o mercado fará.': { en: 'A long position has a positive gross result when the exit price is above the entry price. A short position has a positive gross result when the exit is below entry. The same move can benefit one direction and hurt the other; neither position predicts what the market will do.', es: 'Una posición long tiene un resultado bruto positivo cuando el precio de salida supera al de entrada. Una posición short tiene un resultado bruto positivo cuando la salida queda por debajo de la entrada. El mismo movimiento puede beneficiar a una dirección y perjudicar a la otra; ninguna permite anticipar lo que hará el mercado.' },
  'A comparação do laboratório usa uma posição linear, com quantidade expressa em BTC e resultado na moeda dos preços. É um modelo para aprender o mecanismo. Contratos inversos, opções e outros produtos têm fórmulas diferentes e não devem ser interpretados a partir dessa conta simplificada.': { en: 'The simulator compares linear positions, with size expressed in BTC and results in the price currency. It is a model for learning the mechanism. Inverse contracts, options, and other products use different formulas and should not be interpreted through this simplified calculation.', es: 'La comparación del simulador utiliza posiciones lineales, con la cantidad expresada en BTC y el resultado en la moneda de los precios. Es un modelo para aprender el mecanismo. Los contratos inversos, las opciones y otros productos utilizan fórmulas distintas y no deben interpretarse a partir de este cálculo simplificado.' },
  'Vender Bitcoin que você tem não é abrir short': { en: 'Selling Bitcoin you own is not the same as opening a short', es: 'Vender Bitcoin que tienes no es lo mismo que abrir un short' },
  'Vender uma quantidade de BTC que já está na carteira encerra ou reduz essa posse. Abrir uma posição short cria uma exposição que perde valor quando o preço sobe. Em futuros, é possível assumir essa direção por meio do contrato sem possuir o Bitcoin à vista, como explica a documentação de criptoderivativos da CME.': { en: 'Selling BTC already in your wallet closes or reduces that holding. Opening a short creates exposure that loses value when the price rises. With futures, a contract can create this exposure without owning spot Bitcoin, as CME’s crypto derivatives documentation explains.', es: 'Vender BTC que ya tienes en la billetera cierra o reduce esa tenencia. Abrir una posición short crea una exposición que pierde valor cuando sube el precio. Con futuros, es posible asumir esa dirección mediante un contrato sin poseer Bitcoin spot, como explica la documentación de derivados cripto de CME.' },
  'Também existe venda com ativo emprestado, que envolve condições de empréstimo e devolução. Esses mecanismos não são intercambiáveis. Antes de usar uma plataforma, é necessário identificar qual produto está sendo oferecido, como a obrigação é encerrada e quais custos ou garantias são exigidos.': { en: 'Selling a borrowed asset is another method, with its own borrowing and repayment terms. These mechanisms are not interchangeable. Before using a platform, identify the product, how the obligation is closed, and what costs or collateral are required.', es: 'También se puede vender un activo prestado, lo que implica condiciones de préstamo y devolución. Estos mecanismos no son intercambiables. Antes de utilizar una plataforma, identifica qué producto ofrece, cómo se cierra la obligación y qué costos o garantías requiere.' },
  'Compare as duas direções com a mesma quantidade': { en: 'Compare both directions using the same quantity', es: 'Compara ambas direcciones con la misma cantidad' },
  'Para long, calculamos quantidade × (saída − entrada). Para short, quantidade × (entrada − saída). Ao fixar entrada e quantidade, comparamos a direção sem mudar o tamanho. Todos os preços são fictícios, em USDT por BTC. No simulador, selecione quantidade fixa, zere as taxas de entrada e saída e informe funding zero para reproduzir o exemplo.': { en: 'For a long, we calculate size × (exit − entry). For a short, size × (entry − exit). Fixing entry and size lets us compare direction without changing position size. All prices are hypothetical, in USDT per BTC. To reproduce the example in the simulator, select fixed size, set entry and exit fees to zero, and enter zero funding.', es: 'Para un long, calculamos cantidad × (salida − entrada). Para un short, cantidad × (entrada − salida). Al fijar la entrada y la cantidad, comparamos la dirección sin cambiar el tamaño. Todos los precios son hipotéticos, en USDT por BTC. Para reproducir el ejemplo en el simulador, selecciona cantidad fija, establece en cero las comisiones de entrada y salida e indica funding cero.' },
  'O exemplo é bruto e considera encerramento integral no preço informado. O painel distingue resultado bruto e líquido: o líquido desconta taxas informadas e funding pago, ou soma funding recebido. Uma variação favorável não é lucro realizado enquanto a posição permanece aberta. Marcação, negociação e valor disponível para saque também podem representar coisas diferentes.': { en: 'The example is gross and assumes the entire position closes at the stated price. The panel distinguishes gross and net results: net results subtract entered fees and funding paid, or add funding received. A favorable move is not a realized profit while the position remains open. Marked value, tradable value, and withdrawable value may also differ.', es: 'El ejemplo es bruto y supone que la posición completa se cierra al precio indicado. El panel distingue entre resultados brutos y netos: el resultado neto resta las comisiones indicadas y el funding pagado, o suma el funding recibido. Un movimiento favorable no es una ganancia realizada mientras la posición siga abierta. El valor de mercado, el valor negociable y el valor disponible para retirar también pueden ser distintos.' },
  'A porcentagem depende da base usada': { en: 'The percentage depends on the base used', es: 'El porcentaje depende de la base utilizada' },
  'No exemplo, 60 USDT correspondem a 2% da exposição inicial de 3.000 USDT. Se um cenário de derivativo usa 600 USDT de margem para essa mesma exposição, 60 USDT representam 10% da margem. A diferença está no denominador; o resultado em USDT permanece o mesmo enquanto a quantidade não muda.': { en: 'In the example, 60 USDT is 2% of the initial exposure of 3,000 USDT. If a derivatives scenario uses 600 USDT of margin for the same exposure, 60 USDT is 10% of margin. The denominator differs; the USDT result stays the same as long as position size does not change.', es: 'En el ejemplo, 60 USDT equivalen al 2% de una exposición inicial de 3.000 USDT. Si un escenario de derivados utiliza 600 USDT de margen para esa misma exposición, 60 USDT representan el 10% del margen. Cambia el denominador; el resultado en USDT se mantiene mientras no cambie la cantidad.' },
  'Taxas e, quando aplicável, funding ou juros de empréstimo alteram o resultado líquido. Preço de entrada e saída iguais podem gerar perda líquida por custos. No caso de posições vendidas, uma alta não tem teto teórico de preço; isso exige atenção às obrigações do produto e aos mecanismos de encerramento.': { en: 'Fees and, where applicable, funding or borrowing interest change the net result. Equal entry and exit prices can still produce a net loss due to costs. For short positions, there is no theoretical cap on how high the price can rise; pay attention to product obligations and closing mechanisms.', es: 'Las comisiones y, cuando corresponda, el funding o los intereses del préstamo modifican el resultado neto. Un mismo precio de entrada y salida puede generar una pérdida neta debido a los costos. En las posiciones short, el precio no tiene un límite teórico al alza; presta atención a las obligaciones del producto y a los mecanismos de cierre.' },
  'Use o simulador para testar compreensão': { en: 'Use the simulator to test your understanding', es: 'Usa el simulador para comprobar lo que has entendido' },
  'Experimente uma saída acima e outra abaixo da entrada. Antes de olhar o painel, tente prever apenas o sinal do resultado para cada direção. Depois compare margem e exposição separadamente. Esse exercício verifica compreensão do contrato sem exigir uma previsão de preço.': { en: 'Try an exit above and another below entry. Before looking at the panel, predict only the sign of the result for each direction. Then compare margin and exposure separately. This tests your understanding of the contract without requiring a price forecast.', es: 'Prueba una salida por encima y otra por debajo de la entrada. Antes de mirar el panel, intenta predecir solo el signo del resultado para cada dirección. Después compara el margen y la exposición por separado. Este ejercicio comprueba que entiendes el contrato sin exigir una predicción del precio.' },
  'O laboratório considera as taxas informadas e o funding acumulado em USDT: positivo significa pago; negativo, recebido. Ele não prevê funding futuro, preço de liquidação nem envia ordens. Requisitos de manutenção e regras da corretora podem encerrar a posição antes da saída. O cenário ensina o cálculo linear; operar um produto real exige compreender suas condições.': { en: 'The simulator includes entered fees and accumulated funding in USDT: positive funding is paid; negative funding is received. It does not predict future funding or liquidation price, and it does not send orders. Maintenance requirements and exchange rules may close the position before its planned exit. This scenario teaches the linear calculation; trading a real product requires understanding its terms.', es: 'El simulador incluye las comisiones indicadas y el funding acumulado en USDT: el funding positivo se paga y el negativo se recibe. No predice el funding futuro ni el precio de liquidación, y no envía órdenes. Los requisitos de mantenimiento y las reglas del exchange pueden cerrar la posición antes de la salida prevista. El escenario enseña el cálculo lineal; operar con un producto real exige entender sus condiciones.' },
  'Alavancagem: margem fixa e exposição fixa são comparações diferentes': { en: 'Leverage: fixed margin and fixed exposure are different comparisons', es: 'Apalancamiento: margen fijo y exposición fija son comparaciones distintas' },
  'Veja por que aumentar a alavancagem pode mudar a quantidade ou apenas a margem usada, dependendo do que permanece fixo.': { en: 'See why increasing leverage may change the position size or only the margin used, depending on what stays fixed.', es: 'Descubre por qué aumentar el apalancamiento puede cambiar la cantidad o solo el margen utilizado, según qué valor se mantenga fijo.' },
  'Pergunte primeiro o que está fixo': { en: 'First ask what is fixed', es: 'Primero pregunta qué se mantiene fijo' },
  'Comparar 2x, 5x e 10x sem dizer o que permanece igual pode levar a uma conclusão errada. Em um modelo simplificado, exposição = margem × alavancagem. Se a margem fica constante, a exposição aumenta. Se a exposição fica constante, a margem necessária diminui. São duas experiências distintas, embora o seletor de alavancagem pareça o mesmo.': { en: 'Comparing 2x, 5x, and 10x without saying what stays the same can lead to a wrong conclusion. In a simplified model, exposure = margin × leverage. If margin stays constant, exposure increases. If exposure stays constant, required margin decreases. These are different experiments, even though the leverage selector looks the same.', es: 'Comparar 2x, 5x y 10x sin indicar qué se mantiene igual puede llevar a una conclusión errónea. En un modelo simplificado, exposición = margen × apalancamiento. Si el margen permanece constante, aumenta la exposición. Si la exposición permanece constante, disminuye el margen necesario. Son dos experimentos distintos, aunque el selector de apalancamiento parezca el mismo.' },
  'Margem é a garantia associada ao contrato, enquanto exposição representa o tamanho econômico da posição. A CME distingue margem inicial e margem de manutenção. Os produtos de uma plataforma cripto podem adotar regras próprias; o laboratório usa uma relação idealizada para explicar os números, sem reproduzir um contrato específico.': { en: 'Margin is collateral associated with a contract, while exposure represents the position’s economic size. CME distinguishes initial margin from maintenance margin. Crypto platforms may use their own product rules; the simulator uses an idealized relationship to explain the figures and does not reproduce a specific contract.', es: 'El margen es la garantía asociada al contrato, mientras que la exposición representa el tamaño económico de la posición. CME distingue entre margen inicial y margen de mantenimiento. Las plataformas cripto pueden aplicar reglas propias; el simulador utiliza una relación idealizada para explicar las cifras, no para reproducir un contrato específico.' },
  'Margem fixa: muda a exposição': { en: 'Fixed margin: exposure changes', es: 'Margen fijo: cambia la exposición' },
  'Selecione margem fixa e informe 500 USDT. Para reproduzir as contas abaixo, zere ambas as taxas e o funding. A 2x, a exposição é 1.000 USDT. A 5x, 2.500 USDT. A 10x, 5.000 USDT. Na mesma entrada, isso representa quantidades diferentes. Um movimento de 2% produz resultados em dinheiro diferentes porque o tamanho mudou.': { en: 'Select fixed margin and enter 500 USDT. Set both fees and funding to zero to reproduce the calculations below. At 2x, exposure is 1,000 USDT; at 5x, 2,500 USDT; at 10x, 5,000 USDT. At the same entry price, these represent different position sizes. A 2% move produces different cash results because size changed.', es: 'Selecciona margen fijo e introduce 500 USDT. Para reproducir los cálculos siguientes, establece en cero las comisiones y el funding. A 2x, la exposición es de 1.000 USDT; a 5x, de 2.500 USDT; a 10x, de 5.000 USDT. Con el mismo precio de entrada, representan cantidades distintas. Un movimiento del 2% produce resultados monetarios diferentes porque cambió el tamaño.' },
  'Para um long e um movimento favorável de 2%, os ganhos brutos seriam 20 USDT, 50 USDT e 100 USDT. Com o mesmo movimento contrário, as perdas brutas seriam esses valores. A comparação mostra mais sensibilidade em USDT por manter a margem e aumentar a exposição, não por alterar a fórmula do resultado da quantidade já fixada.': { en: 'For a long, a favorable 2% move would produce gross gains of 20, 50, and 100 USDT. The same move in the opposite direction would produce losses of those amounts. The comparison shows greater sensitivity in USDT because margin is held constant and exposure increases, not because the result formula for a fixed size changes.', es: 'En un long, un movimiento favorable del 2% produciría ganancias brutas de 20, 50 y 100 USDT. El mismo movimiento en contra produciría pérdidas de esos importes. La comparación muestra una mayor sensibilidad en USDT porque el margen se mantiene y aumenta la exposición, no porque cambie la fórmula del resultado para una cantidad fija.' },
  'Exposição fixa: muda a margem': { en: 'Fixed exposure: margin changes', es: 'Exposición fija: cambia el margen' },
  'Agora selecione quantidade fixa. Com entrada fictícia de 300.000 USDT por BTC, aproximadamente 0,016667 BTC representam 5.000 USDT de exposição. A margem simplificada é 2.500 USDT a 2x, 1.000 USDT a 5x e 500 USDT a 10x. Uma variação adversa de 2% continua produzindo aproximadamente 100 USDT de perda bruta, desde que a quantidade seja mantida e a posição não seja encerrada antes.': { en: 'Now select fixed position size. With a hypothetical entry of 300,000 USDT per BTC, approximately 0.016667 BTC represents 5,000 USDT of exposure. Simplified margin is 2,500 USDT at 2x, 1,000 USDT at 5x, and 500 USDT at 10x. An adverse 2% move still produces approximately 100 USDT in gross loss, as long as size stays fixed and the position is not closed first.', es: 'Ahora selecciona cantidad fija. Con una entrada hipotética de 300.000 USDT por BTC, aproximadamente 0,016667 BTC representan una exposición de 5.000 USDT. El margen simplificado es de 2.500 USDT a 2x, 1.000 USDT a 5x y 500 USDT a 10x. Un movimiento adverso del 2% sigue produciendo una pérdida bruta aproximada de 100 USDT, siempre que la cantidad se mantenga y la posición no se cierre antes.' },
  'A perda representa 4%, 10% e 20% das margens respectivas. Uma porcentagem maior sobre a margem não significa que a perda em USDT aumentou neste exercício. Ela indica que há menos garantia inicial em relação à mesma exposição. A folga frente aos requisitos de manutenção pode diminuir.': { en: 'The loss represents 4%, 10%, and 20% of the respective margins. A higher percentage of margin does not mean the USDT loss increased in this exercise. It means there is less initial collateral for the same exposure. The buffer above maintenance requirements may shrink.', es: 'La pérdida representa el 4%, 10% y 20% de los respectivos márgenes. Un porcentaje mayor del margen no significa que la pérdida en USDT haya aumentado en este ejercicio. Indica que hay menos garantía inicial para la misma exposición. El margen de seguridad frente a los requisitos de mantenimiento puede reducirse.' },
  'Liquidação não é simplesmente 1 dividido pela alavancagem': { en: 'Liquidation is not simply 1 divided by leverage', es: 'La liquidación no es simplemente 1 dividido por el apalancamiento' },
  'Uma conta como “10x suporta exatamente 10% de queda” ignora manutenção, taxas e regras de preço. Também não considera margem compartilhada entre posições. O saldo disponível e o mecanismo de liquidação precisam ser avaliados conforme o contrato; não existe um preço universal que o simulador possa garantir.': { en: 'A calculation such as “10x can withstand exactly a 10% drop” ignores maintenance, fees, and pricing rules. It also ignores margin shared across positions. Available balance and liquidation mechanics must be assessed under the contract; there is no universal price the simulator can guarantee.', es: 'Un cálculo como “10x soporta exactamente una caída del 10%” ignora el mantenimiento, las comisiones y las reglas de precios. Tampoco considera el margen compartido entre posiciones. El saldo disponible y los mecanismos de liquidación deben evaluarse según el contrato; no existe un precio universal que el simulador pueda garantizar.' },
  'A CFTC alerta que contratos alavancados ampliam riscos e podem exigir reforço de margem ou encerramento. Aqui a explicação serve para compreender a exposição. A margem mostrada não deve ser interpretada como limite absoluto de perda nem como reserva suficiente para sustentar qualquer trajetória de preço.': { en: 'The CFTC warns that leveraged contracts amplify risk and may require additional margin or position closure. This explanation is intended to help you understand exposure. The displayed margin should not be interpreted as an absolute loss limit or enough collateral to withstand any price path.', es: 'La CFTC advierte que los contratos apalancados amplifican los riesgos y pueden exigir más margen o el cierre de la posición. Esta explicación sirve para comprender la exposición. El margen mostrado no debe interpretarse como un límite absoluto de pérdidas ni como garantía suficiente para soportar cualquier trayectoria de precios.' },
  'Leia o painel sem misturar denominadores': { en: 'Read the panel without mixing denominators', es: 'Lee el panel sin mezclar denominadores' },
  'Ao comparar cenários, anote entrada, direção, quantidade, exposição, margem e saída. Se uma dessas informações muda, identifique qual efeito está sendo medido. “Resultado sobre a margem” e “variação do ativo” respondem a perguntas diferentes e precisam aparecer com seus nomes.': { en: 'When comparing scenarios, record entry, direction, size, exposure, margin, and exit. If one of these changes, identify which effect is being measured. “Return on margin” and “asset price change” answer different questions and should be labeled accordingly.', es: 'Al comparar escenarios, anota la entrada, la dirección, la cantidad, la exposición, el margen y la salida. Si cambia uno de estos datos, identifica qué efecto se está midiendo. “Resultado sobre el margen” y “variación del activo” responden a preguntas distintas y deben indicarse por separado.' },
  'O painel mostra resultado bruto e líquido, incluindo taxas de entrada e saída e funding acumulado informado. Funding positivo é pago; negativo é recebido. O modelo não prevê funding futuro, juros de empréstimo, slippage ou liquidação. Refaça o exercício com movimento adverso e observe o valor em USDT. O aprendizado é reconhecer quando a posição aumentou e quando apenas a garantia foi reduzida.': { en: 'The panel shows gross and net results, including entered entry and exit fees and accumulated funding. Positive funding is paid; negative funding is received. The model does not predict future funding, borrowing interest, slippage, or liquidation. Repeat the exercise with an adverse move and watch the USDT value. The lesson is to recognize when position size increased and when only collateral decreased.', es: 'El panel muestra los resultados brutos y netos, incluidas las comisiones de entrada y salida indicadas y el funding acumulado. El funding positivo se paga; el negativo se recibe. El modelo no predice el funding futuro, los intereses del préstamo, el slippage ni las liquidaciones. Repite el ejercicio con un movimiento adverso y observa el valor en USDT. La idea es reconocer cuándo aumentó la posición y cuándo solo se redujo la garantía.' },
  'Caiu 50%: por que precisa subir 100% para recuperar?': { en: 'Down 50%: why does it take a 100% gain to recover?', es: 'Cayó un 50%: ¿por qué necesita subir un 100% para recuperarse?' },
  'Entenda a mudança de base dos percentuais, perdas consecutivas e a diferença entre recuperação do preço e da carteira.': { en: 'Understand how percentage bases change, how consecutive losses work, and the difference between a price recovery and a portfolio recovery.', es: 'Comprende cómo cambia la base de los porcentajes, las pérdidas consecutivas y la diferencia entre la recuperación del precio y la de la cartera.' },
  'A porcentagem muda de base': { en: 'The percentage uses a new base', es: 'El porcentaje cambia de base' },
  'A fórmula usa o capital que sobrou': { en: 'The formula uses the capital that remains', es: 'La fórmula utiliza el capital restante' },
  'Perdas consecutivas não se somam diretamente': { en: 'Consecutive losses do not add up directly', es: 'Las pérdidas consecutivas no se suman directamente' },
  'O preço e a carteira podem ter recuperações diferentes': { en: 'The price and the portfolio may recover differently', es: 'El precio y la cartera pueden recuperarse de forma distinta' },
  'Transforme o número em uma pergunta melhor': { en: 'Turn the number into a better question', es: 'Convierte la cifra en una pregunta mejor' },
  'Banca: 6.000 USDT. Risco: 1%. Taxas: zero. Entrada: 300.000 USDT por BTC. Stop: 294.000 USDT por BTC. Quantidade calculada: 0,01 BTC. Perda planejada: (300.000 − 294.000) × 0,01 = 60 USDT. Exposição na entrada: 3.000 USDT.': { en: 'Capital: 6,000 USDT. Risk: 1%. Fees: zero. Entry: 300,000 USDT per BTC. Stop: 294,000 USDT per BTC. Calculated size: 0.01 BTC. Planned loss: (300,000 − 294,000) × 0.01 = 60 USDT. Entry exposure: 3,000 USDT.', es: 'Capital: 6.000 USDT. Riesgo: 1%. Comisiones: cero. Entrada: 300.000 USDT por BTC. Stop: 294.000 USDT por BTC. Cantidad calculada: 0,01 BTC. Pérdida prevista: (300.000 − 294.000) × 0,01 = 60 USDT. Exposición en la entrada: 3.000 USDT.' },
  'Banca: 10.000 USDT. Risco fictício: 1%, ou 100 USDT. Entrada: 300.000 USDT por BTC. Stop: 294.000 USDT. Quantidade: 100 ÷ 6.000 = aproximadamente 0,016667 BTC. Exposição: aproximadamente 5.000 USDT, antes de custos.': { en: 'Capital: 10,000 USDT. Hypothetical risk: 1%, or 100 USDT. Entry: 300,000 USDT per BTC. Stop: 294,000 USDT. Position size: 100 ÷ 6,000 = approximately 0.016667 BTC. Exposure: approximately 5,000 USDT, before costs.', es: 'Capital: 10.000 USDT. Riesgo hipotético: 1%, o 100 USDT. Entrada: 300.000 USDT por BTC. Stop: 294.000 USDT. Cantidad: 100 ÷ 6.000 = aproximadamente 0,016667 BTC. Exposición: aproximadamente 5.000 USDT, antes de costos.' },
  'Entrada: 300.000 USDT por BTC. Quantidade: 0,01 BTC. Saída a 306.000 USDT: long +60 USDT e short −60 USDT. Saída a 294.000 USDT: long −60 USDT e short +60 USDT, antes de custos.': { en: 'Entry: 300,000 USDT per BTC. Size: 0.01 BTC. Exit at 306,000 USDT: long +60 USDT and short −60 USDT. Exit at 294,000 USDT: long −60 USDT and short +60 USDT, before costs.', es: 'Entrada: 300.000 USDT por BTC. Cantidad: 0,01 BTC. Salida a 306.000 USDT: long +60 USDT y short −60 USDT. Salida a 294.000 USDT: long −60 USDT y short +60 USDT, antes de costos.' },
  'Cálculo simplificado: 1.000 USDT × 0,0001 = 0,10 USDT. Exemplo hipotético, não é taxa atual.': { en: 'Simplified calculation: 1,000 USDT × 0.0001 = 0.10 USDT. Hypothetical example; this is not the current rate.', es: 'Cálculo simplificado: 1.000 USDT × 0,0001 = 0,10 USDT. Ejemplo hipotético; no es la tasa actual.' },
  'Os números são inventados para ilustrar a diferença entre estoque de contratos abertos e fluxo de negociações.': { en: 'These figures are made up to illustrate the difference between the stock of open contracts and the flow of trades.', es: 'Estas cifras son inventadas para ilustrar la diferencia entre el conjunto de contratos abiertos y el flujo de operaciones.' },
  '500 USDT de margem × 10 = 5.000 USDT de exposição. Variação de −2% em um long linear: −100 USDT antes de custos, equivalente a −20% da margem inicial.': { en: '500 USDT margin × 10 = 5,000 USDT exposure. A −2% move on a linear long: −100 USDT before costs, equal to −20% of initial margin.', es: '500 USDT de margen × 10 = 5.000 USDT de exposición. Variación de −2% en un long lineal: −100 USDT antes de costos, equivalente al −20% del margen inicial.' },
  '10.000 USDT com perda de 30% deixam 7.000 USDT. Faltam 3.000 USDT para recuperar. 3.000 USDT ÷ 7.000 USDT × 100 = aproximadamente 42,86% de alta necessária.': { en: 'A 30% loss on 10,000 USDT leaves 7,000 USDT. It takes 3,000 USDT to recover. 3,000 USDT ÷ 7,000 USDT × 100 = approximately 42.86% required gain.', es: 'Una pérdida del 30% sobre 10.000 USDT deja 7.000 USDT. Faltan 3.000 USDT para recuperarse. 3.000 USDT ÷ 7.000 USDT × 100 = aproximadamente un 42,86% de subida necesaria.' },
  'Se 1.000 USDT caem para 500 USDT, a perda é 500 USDT: metade do valor inicial. Para voltar de 500 USDT a 1.000 USDT, é preciso ganhar os mesmos 500 USDT, mas agora esse ganho equivale a todo o saldo restante. Por isso uma queda de 50% exige uma alta de 100% para retornar ao ponto inicial.': { en: 'If 1,000 USDT falls to 500 USDT, the loss is 500 USDT: half the initial value. To return from 500 USDT to 1,000 USDT, the same 500 USDT must be gained, but that gain now equals the entire remaining balance. That is why a 50% decline requires a 100% gain to return to the starting point.', es: 'Si 1.000 USDT bajan a 500 USDT, la pérdida es de 500 USDT: la mitad del valor inicial. Para volver de 500 USDT a 1.000 USDT, hay que ganar los mismos 500 USDT, pero ahora esa ganancia equivale a todo el saldo restante. Por eso, una caída del 50% exige una subida del 100% para regresar al punto inicial.' },
  'Esse resultado é aritmético. Ele não informa se o ativo irá recuperar, quanto tempo isso levaria ou qual operação produziria o ganho. A calculadora foi criada para tornar a mudança de base visível e evitar interpretar percentuais de queda e alta como movimentos automaticamente simétricos.': { en: 'This is an arithmetic result. It does not indicate whether the asset will recover, how long that would take, or which trade would produce the gain. The calculator makes the change in percentage base visible and helps avoid treating declines and gains as automatically symmetrical moves.', es: 'Este es un resultado aritmético. No indica si el activo se recuperará, cuánto tardaría ni qué operación produciría la ganancia. La calculadora muestra el cambio en la base porcentual y ayuda a evitar interpretar las caídas y subidas como movimientos automáticamente simétricos.' },
  'Para uma perda percentual p, o saldo restante é o capital inicial multiplicado por (1 − p/100). A alta necessária, em percentual, é p ÷ (100 − p) × 100. A fórmula vale para perdas entre zero e menos de 100%, sem aportes, retiradas ou custos no intervalo.': { en: 'For a percentage loss p, the remaining balance is the initial capital multiplied by (1 − p/100). The required gain, as a percentage, is p ÷ (100 − p) × 100. The formula applies to losses from zero up to, but not including, 100%, with no deposits, withdrawals, or costs in between.', es: 'Para una pérdida porcentual p, el saldo restante es el capital inicial multiplicado por (1 − p/100). La subida necesaria, en porcentaje, es p ÷ (100 − p) × 100. La fórmula se aplica a pérdidas desde cero hasta menos del 100%, sin aportes, retiros ni costos durante el intervalo.' },
  'Uma queda de 20% exige alta de 25%; uma queda de 40% exige aproximadamente 66,67%. Quanto menor o saldo restante, maior é a porcentagem necessária sobre ele. Na perda de 100%, o saldo é zero e não existe alta percentual finita capaz de reconstruir o capital sem entrada de dinheiro.': { en: 'A 20% decline requires a 25% gain; a 40% decline requires approximately 66.67%. The smaller the remaining balance, the larger the percentage gain needed on it. After a 100% loss, the balance is zero, and no finite percentage gain can rebuild the capital without adding money.', es: 'Una caída del 20% exige una subida del 25%; una caída del 40% exige aproximadamente un 66,67%. Cuanto menor sea el saldo restante, mayor será el porcentaje de subida necesario sobre ese saldo. Tras una pérdida del 100%, el saldo es cero y ninguna subida porcentual finita puede reconstruir el capital sin aportar dinero.' },
  'Duas quedas de 10% não produzem exatamente 20% de perda quando cada uma incide sobre o saldo daquele momento. Partindo de 1.000 USDT, a primeira deixa 900 USDT e a segunda deixa 810 USDT. A perda acumulada é de 19%, e a alta necessária para voltar a 1.000 USDT é aproximadamente 23,46%.': { en: 'Two 10% declines do not produce exactly a 20% loss when each applies to the balance at that point. Starting with 1,000 USDT, the first leaves 900 USDT and the second leaves 810 USDT. The cumulative loss is 19%, and a gain of approximately 23.46% is needed to return to 1,000 USDT.', es: 'Dos caídas del 10% no producen exactamente una pérdida del 20% cuando cada una se aplica al saldo de ese momento. A partir de 1.000 USDT, la primera deja 900 USDT y la segunda, 810 USDT. La pérdida acumulada es del 19%, y se necesita una subida de aproximadamente el 23,46% para volver a 1.000 USDT.' },
  'Uma queda de 10% seguida de alta de 10% também não zera a diferença: 1.000 USDT viram 900 USDT e depois 990 USDT. O ganho foi calculado sobre uma base menor. Esse exemplo ajuda a entender resultados compostos e por que somar percentuais de dias diferentes pode distorcer o desempenho.': { en: 'A 10% decline followed by a 10% gain also does not erase the difference: 1,000 USDT becomes 900 USDT and then 990 USDT. The gain was calculated on a smaller base. This example helps explain compounding and why adding percentages from different days can distort performance.', es: 'Una caída del 10% seguida de una subida del 10% tampoco elimina la diferencia: 1.000 USDT se convierten en 900 USDT y luego en 990 USDT. La ganancia se calculó sobre una base menor. Este ejemplo ayuda a entender la capitalización y por qué sumar porcentajes de días distintos puede distorsionar el rendimiento.' },
  'Se você manteve a mesma quantidade de um ativo, sem custos ou movimentações, a recuperação percentual da posição acompanha a do preço. Quando há compras adicionais, vendas parciais, taxas ou outros ativos, a evolução do patrimônio deixa de ser uma cópia simples do gráfico daquele ativo.': { en: 'If you held the same amount of an asset, with no costs or transactions, the position’s percentage recovery tracks the price recovery. With additional purchases, partial sales, fees, or other assets, the portfolio’s performance is no longer a simple copy of that asset’s chart.', es: 'Si mantuviste la misma cantidad de un activo, sin costos ni movimientos, la recuperación porcentual de la posición sigue a la del precio. Cuando hay compras adicionales, ventas parciales, comisiones u otros activos, la evolución del patrimonio deja de ser una copia simple del gráfico de ese activo.' },
  'Um aporte pode restaurar o saldo da conta sem recuperar a perda do investimento. Por exemplo, adicionar 500 USDT a uma carteira que caiu de 1.000 USDT para 500 USDT devolve o saldo a 1.000 USDT, mas a posição original continua valendo 500 USDT. Separar capital novo de rendimento evita atribuir recuperação ao mercado quando ela veio de um depósito.': { en: 'A deposit can restore an account balance without recovering an investment loss. For example, adding 500 USDT to a portfolio that fell from 1,000 USDT to 500 USDT brings the balance back to 1,000 USDT, but the original position is still worth 500 USDT. Separating new capital from returns avoids crediting the market for a recovery that came from a deposit.', es: 'Un aporte puede restaurar el saldo de la cuenta sin recuperar la pérdida de la inversión. Por ejemplo, añadir 500 USDT a una cartera que bajó de 1.000 USDT a 500 USDT devuelve el saldo a 1.000 USDT, pero la posición original sigue valiendo 500 USDT. Separar el capital nuevo del rendimiento evita atribuir al mercado una recuperación que provino de un depósito.' },
  'Em vez de perguntar somente quanto precisa ganhar, investigue como a perda aconteceu e quais hipóteses continuam válidas. A necessidade matemática de uma alta não cria uma oportunidade nem justifica aumentar a posição. A CFTC destaca os riscos dos mercados cripto e de contratos alavancados; a calculadora não escolhe uma forma de compensar perdas.': { en: 'Instead of asking only how much needs to be gained, examine how the loss happened and which assumptions still hold. The mathematical need for a gain does not create an opportunity or justify increasing a position. The CFTC highlights risks in crypto markets and leveraged contracts; this calculator does not choose a way to make up for losses.', es: 'En vez de preguntar solo cuánto hay que ganar, analiza cómo ocurrió la pérdida y qué hipótesis siguen siendo válidas. La necesidad matemática de una subida no crea una oportunidad ni justifica aumentar la posición. La CFTC destaca los riesgos de los mercados cripto y los contratos apalancados; esta calculadora no elige una forma de compensar las pérdidas.' },
  'Experimente comparar quedas de 10%, 30% e 60% com o mesmo capital inicial. Observe tanto a alta necessária quanto o saldo restante. A ferramenta considera um único movimento líquido e valores nominais; não inclui inflação, tributos ou uma sequência real de negociações. A fórmula é uma demonstração própria, e a fonte abaixo oferece contexto de risco, não uma previsão de recuperação.': { en: 'Compare 10%, 30%, and 60% declines using the same initial capital. Look at both the required gain and the remaining balance. The tool models a single net move in nominal values; it does not include inflation, taxes, or a real sequence of trades. The formula is an original illustration, and the source below provides risk context, not a recovery forecast.', es: 'Compara caídas del 10%, 30% y 60% con el mismo capital inicial. Observa tanto la subida necesaria como el saldo restante. La herramienta considera un único movimiento neto y valores nominales; no incluye inflación, impuestos ni una secuencia real de operaciones. La fórmula es una demostración propia y la fuente siguiente ofrece contexto sobre riesgos, no una previsión de recuperación.' },
}
